PathwayData.put("data/reading_writing/units/L03U3.json",{"strand":"reading_writing","level":3,"cefr":"A2a","unit":3,"theme":"Travel and Transport","essential_question":"How do people and things move from place to place?","schema_version":"1.0","core_words":["car","bus","train","plane","ship","bicycle","airport","station","ticket","passenger","journey","map","fast","slow"],"recycled_words":["camel","desert","first","then","finally","before","after","morning","night","because","so","heading","grandpa"],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L03-U3-LS1","title":"Word Power: Travel and Transport","lesson_type":"vocabulary","objectives":["read, say and use 14 words about travel and transport and 3 Tier 2 words (transport, sequence, invent)","split compound words into two smaller words to find their meaning (air + port = airport)","build word families from one base word (travel, traveler, traveling)"],"objectives_ar":["قراءة ونطق واستخدام 14 كلمة عن السفر والمواصلات و3 كلمات أكاديمية (transport, sequence, invent).","تقسيم الكلمات المركبة إلى كلمتين أصغر لمعرفة معناها.","بناء عائلات كلمات من كلمة أساسية واحدة."],"success_criteria":["I can read and use the travel words in sentences.","I can split a compound word and explain its meaning.","I can find words in the same word family."],"success_criteria_ar":["أستطيع قراءة كلمات السفر واستخدامها في جمل.","أستطيع تقسيم الكلمة المركبة وشرح معناها.","أستطيع إيجاد كلمات من العائلة نفسها."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"car","pos":"noun","ipa":"/kɑr/","definition":"a vehicle with four wheels for a few people","arabic":"سيارة","example":"We drove to Jeddah by car.","image_id":"IMG-RW-L03-U3-LS1-V01","audio_id":"AUD-RW-L03-U3-LS1-V01","tier":"core"},{"word":"bus","pos":"noun","ipa":"/bʌs/","definition":"a big vehicle that carries many people","arabic":"حافلة","example":"The school bus comes at seven.","image_id":"IMG-RW-L03-U3-LS1-V02","audio_id":"AUD-RW-L03-U3-LS1-V02","tier":"core"},{"word":"train","pos":"noun","ipa":"/treɪn/","definition":"a long line of cars that move on rails","arabic":"قطار","example":"The train goes from Makkah to Madinah.","image_id":"IMG-RW-L03-U3-LS1-V03","audio_id":"AUD-RW-L03-U3-LS1-V03","tier":"core"},{"word":"plane","pos":"noun","ipa":"/pleɪn/","definition":"a vehicle that flies in the sky","arabic":"طائرة","example":"The plane landed in Riyadh.","image_id":"IMG-RW-L03-U3-LS1-V04","audio_id":"AUD-RW-L03-U3-LS1-V04","tier":"core"},{"word":"ship","pos":"noun","ipa":"/ʃɪp/","definition":"a very big boat that travels on the sea","arabic":"سفينة","example":"The ship sailed across the Red Sea.","image_id":"IMG-RW-L03-U3-LS1-V05","audio_id":"AUD-RW-L03-U3-LS1-V05","tier":"core"},{"word":"bicycle","pos":"noun","ipa":"/ˈbaɪsɪkəl/","definition":"a vehicle with two wheels that you pedal","arabic":"دراجة هوائية","example":"Faris rides his bicycle in the park.","image_id":"IMG-RW-L03-U3-LS1-V06","audio_id":"AUD-RW-L03-U3-LS1-V06","tier":"core"},{"word":"airport","pos":"noun","ipa":"/ˈɛrpɔrt/","definition":"a place where planes take off and land","arabic":"مطار","example":"We met Grandpa at the airport.","image_id":"IMG-RW-L03-U3-LS1-V07","audio_id":"AUD-RW-L03-U3-LS1-V07","tier":"core"},{"word":"station","pos":"noun","ipa":"/ˈsteɪʃən/","definition":"a place where trains or buses stop for passengers","arabic":"محطة","example":"The train station is very modern.","image_id":"IMG-RW-L03-U3-LS1-V08","audio_id":"AUD-RW-L03-U3-LS1-V08","tier":"core"},{"word":"ticket","pos":"noun","ipa":"/ˈtɪkɪt/","definition":"a paper or code that shows you paid to travel","arabic":"تذكرة","example":"Show your ticket to the driver.","image_id":"IMG-RW-L03-U3-LS1-V09","audio_id":"AUD-RW-L03-U3-LS1-V09","tier":"core"},{"word":"passenger","pos":"noun","ipa":"/ˈpæsɪndʒər/","definition":"a person who travels in a car, bus, train, plane or ship but does not drive it","arabic":"راكب","example":"The plane has 200 passengers.","image_id":"IMG-RW-L03-U3-LS1-V10","audio_id":"AUD-RW-L03-U3-LS1-V10","tier":"core"},{"word":"journey","pos":"noun","ipa":"/ˈdʒɝni/","definition":"a trip from one place to another, often a long one","arabic":"رحلة","example":"The journey took three hours.","image_id":"IMG-RW-L03-U3-LS1-V11","audio_id":"AUD-RW-L03-U3-LS1-V11","tier":"core"},{"word":"map","pos":"noun","ipa":"/mæp/","definition":"a drawing that shows where places are","arabic":"خريطة","example":"Look at the map to find Taif.","image_id":"IMG-RW-L03-U3-LS1-V12","audio_id":"AUD-RW-L03-U3-LS1-V12","tier":"core"},{"word":"fast","pos":"adjective / adverb","ipa":"/fæst/","definition":"moving quickly","arabic":"سريع","example":"The train is very fast.","image_id":"IMG-RW-L03-U3-LS1-V13","audio_id":"AUD-RW-L03-U3-LS1-V13","tier":"core"},{"word":"slow","pos":"adjective","ipa":"/sloʊ/","definition":"not fast","arabic":"بطيء","example":"Camels are slow but strong.","image_id":"IMG-RW-L03-U3-LS1-V14","audio_id":"AUD-RW-L03-U3-LS1-V14","tier":"core"},{"word":"transport","pos":"noun","ipa":"/ˈtrænspɔrt/","definition":"the ways people and things move from place to place","arabic":"المواصلات / النقل","example":"Trains are a fast kind of transport.","image_id":"IMG-RW-L03-U3-LS1-V15","audio_id":"AUD-RW-L03-U3-LS1-V15","tier":"tier2"},{"word":"sequence","pos":"noun","ipa":"/ˈsikwəns/","definition":"the order in which things happen","arabic":"تسلسل / ترتيب","example":"Put the events in the right sequence.","image_id":"IMG-RW-L03-U3-LS1-V16","audio_id":"AUD-RW-L03-U3-LS1-V16","tier":"tier2"},{"word":"invent","pos":"verb","ipa":"/ɪnˈvɛnt/","definition":"to make something new for the first time","arabic":"يخترع","example":"Who invented the bicycle?","image_id":"IMG-RW-L03-U3-LS1-V17","audio_id":"AUD-RW-L03-U3-LS1-V17","tier":"tier2"}],"explanation":{"text":"A **compound word** is made of **two smaller words** joined together: *air + port = **airport***. To find the meaning, **split** the word and think about both parts: an airport is a **port** (a place where things arrive and leave) for **air** travel.\n\nA **word family** is a group of words that share the **same base word**: *travel, travel**er**, travel**ing**, travel**ed***. If you know the base word, you can guess the meaning of the family.\n\nLook for compound words and word families when you read. They make **new words easier**.","examples":["**air + port = airport** – a place for planes.","**rail + way = railway** – the track that trains move on.","**bus + stop = bus stop** (two words) – where a bus stops.","**sea + port = seaport** – a city where ships arrive.","**suit + case = suitcase** – a bag for clothes on a trip.","**week + end = weekend** – the end of the week.","Word family **travel**: *travel, traveler, traveling, traveled*.","Word family **drive**: *drive, driver, driving, drove*.","Word family **pass**: *pass, passenger, passport*."],"common_errors":["✗ air port → ✓ airport (Many compound words are written as **one word**.)","✗ bustop → ✓ bus stop (Some compound words stay **two words** – check the dictionary.)","✗ travelor → ✓ traveler (American spelling: **traveler** (one l).)","✗ We go to Jeddah by the car. → ✓ We go to Jeddah by car. (Say **by car / by train / by plane** (no 'the').)","✗ The passengers was on the train. → ✓ The passengers were on the train. (Many passengers → **were**.)","✗ The train is more fast. → ✓ The train is faster. (Short adjective + **-er**: faster, slower.)","✗ I rode on my bicycle to school. → ✓ I rode my bicycle to school. (ride + your bicycle (no 'on' needed).)"],"arabic":"الكلمة المركبة تتكوّن من كلمتين أصغر: air + port = airport. لمعرفة معناها قسّمها وفكّر في الجزأين.\n\nعائلة الكلمات مجموعة كلمات تشترك في الكلمة الأساسية نفسها: travel, traveler, traveling.\n\nانتبه: بعض الكلمات المركبة تُكتب كلمة واحدة (airport) وبعضها كلمتين (bus stop).\n\nنقول by car, by train, by plane دون the."},"video":{"script":[{"time":"00:00–00:20","narration":"Pack your bags! Sami is going on a journey across Saudi Arabia!","on_screen":"Travel and Transport","visual":"Sami with a small suitcase in front of a big map."},{"time":"00:20–01:00","narration":"By car, by bus, by train, by plane, by ship – and by bicycle!","on_screen":"car · bus · train · plane · ship · bicycle","visual":"Each vehicle zooms across the map with its sound."},{"time":"01:00–01:30","narration":"At the airport and the station, passengers show their tickets. Fast or slow – every journey needs a map!","on_screen":"airport · station · ticket · passenger · journey · map · fast · slow","visual":"Quick scenes at a station gate and an airport counter."},{"time":"01:30–02:20","narration":"Compound words: air + port = airport! rail + way = railway! suit + case = suitcase!","on_screen":"word + word = compound word","visual":"Two word blocks click together into one."},{"time":"02:20–02:45","narration":"Word families: travel, traveler, traveling, traveled!","on_screen":"Word family 👨‍👩‍👧","visual":"A family tree with 'travel' as the trunk and its family on the branches."},{"time":"02:45–03:00","narration":"People invented new transport, one after another. Let's learn the sequence!","on_screen":"transport · sequence · invent","visual":"A timeline from a camel to a high-speed train."}],"captions_ar":["جهّز حقائبك! سامي ذاهب في رحلة عبر السعودية!","بالسيارة والحافلة والقطار والطائرة والسفينة… والدراجة!","في المطار والمحطة يُظهر الركاب تذاكرهم. سريعة أو بطيئة… كل رحلة تحتاج إلى خريطة!","كلمات مركبة: air + port = airport! rail + way = railway!","عائلات الكلمات: travel, traveler, traveling, traveled!","اخترع الناس وسائل نقل جديدة واحدة بعد أخرى. لنتعلم تسلسلها!"],"voice":"Narrator: American English, cheerful female teacher, speed 0.90. Sami: excited traveler voice."},"texts":[],"activities":[{"id":"RW-L03-U3-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the correct word.","instructions_ar":"اختر الكلمة الصحيحة.","items":[{"q":"Planes take off and land at the ___.","answer":"airport","explanation":"Planes → airport.","explanation_ar":"المطار.","options":["airport","station","bus stop","seaport"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A person who travels on a train but does not drive it is a ___.","answer":"passenger","explanation":"Passenger = traveler.","explanation_ar":"راكب.","options":["driver","passenger","pilot","ticket"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"You show a ___ to get on the train.","answer":"ticket","explanation":"A ticket shows you paid.","explanation_ar":"تذكرة.","options":["map","journey","ticket","station"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A very big boat that travels on the sea is a ___.","answer":"ship","explanation":"Ship = big boat.","explanation_ar":"سفينة.","options":["ship","bicycle","train","bus"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A drawing that shows where places are is a ___.","answer":"map","explanation":"Map = shows places.","explanation_ar":"خريطة.","options":["ticket","map","station","suitcase"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Camels are ___, but the high-speed train is fast.","answer":"slow","explanation":"Opposite of fast.","explanation_ar":"بطيئة.","options":["fast","faster","quick","slow"],"dok":1,"skill":"opposites","stage":"controlled"}]},{"id":"RW-L03-U3-LS1-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Compound words and word families. Choose.","instructions_ar":"الكلمات المركبة وعائلات الكلمات: اختر.","items":[{"q":"Which two words make *railway*?","answer":"rail + way","explanation":"rail + way.","explanation_ar":"rail + way.","options":["rai + lway","rain + way","rail + day","rail + way"],"dok":1,"skill":"compound words","stage":"guided"},{"q":"A *suitcase* is ___.","answer":"a case (bag) for clothes on a trip","explanation":"suit + case.","explanation_ar":"حقيبة ملابس.","options":["a kind of suit","a train","a case (bag) for clothes on a trip","a ticket"],"dok":2,"skill":"compound words","stage":"guided"},{"q":"Which travel word in this list is a compound word?","answer":"seaport","explanation":"sea + port.","explanation_ar":"seaport.","options":["seaport","passenger","station","journey"],"dok":1,"skill":"compound words","stage":"guided"},{"q":"Which compound word for the time when we sometimes travel is spelled correctly?","answer":"weekend","explanation":"Written as one word.","explanation_ar":"weekend.","options":["week end","weakend","weekand","weekend"],"dok":2,"skill":"spelling","stage":"guided"},{"q":"Which word is in the same family as *drive*?","answer":"driver","explanation":"drive → driver.","explanation_ar":"driver.","options":["train","driver","ticket","airport"],"dok":1,"skill":"word families","stage":"guided"},{"q":"*A traveler is a person who ___.*","answer":"travels","explanation":"travel + er = person who travels.","explanation_ar":"يسافر.","options":["drives a bus","sells tickets","travels","builds roads"],"dok":2,"skill":"word families","stage":"guided"}]},{"id":"RW-L03-U3-LS1-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Use the word bank.","instructions_ar":"استخدم بنك الكلمات.","items":[{"q":"Cars, buses and trains are kinds of ________.","answer":"transport","explanation":"Ways to move people and things.","explanation_ar":"مواصلات.","stage":"freer"},{"q":"Put the pictures in the right ________: first, next, last.","answer":"sequence","explanation":"Order.","explanation_ar":"التسلسل.","stage":"freer"},{"q":"Karl Benz helped to ________ one of the first cars.","answer":"invent","explanation":"Make for the first time.","explanation_ar":"يخترع.","stage":"freer"},{"q":"The ________ from Riyadh to Jeddah by car is very long.","answer":"journey","explanation":"A long trip.","explanation_ar":"الرحلة.","stage":"freer"},{"q":"We waited for the train at the ________.","answer":"station","explanation":"Where trains stop.","explanation_ar":"المحطة.","stage":"freer"},{"q":"Faris rides his ________ to the park on Fridays.","answer":"bicycle","explanation":"Two wheels, you pedal.","explanation_ar":"دراجته.","stage":"freer"}]},{"id":"RW-L03-U3-LS1-A4","type":"open","stage":"production","instructions":"Writing: Write with the new words.","instructions_ar":"اكتب باستخدام الكلمات الجديدة.","items":[{"q":"Split *airport* and explain its meaning.","answer":"air + port: a place where planes take off and land.","explanation":"Two parts + meaning.","explanation_ar":"جزآن + معنى.","dok":2,"skill":"compound words","stage":"production"},{"q":"Write three words in the *travel* family and use one in a sentence.","answer":"travel, traveler, traveling – My uncle is a traveler; he visits many countries.","explanation":"Family + sentence.","explanation_ar":"العائلة + جملة.","dok":2,"skill":"word families","stage":"production"},{"q":"What is your favorite kind of transport? Why?","answer":"My favorite is the train because it is fast and I can look out of the window.","explanation":"Transport + because.","explanation_ar":"وسيلة + because.","dok":2,"skill":"opinion","stage":"production"},{"q":"Compare two kinds of transport using *fast/faster* or *slow/slower*.","answer":"A plane is faster than a car, but a car can take you to your door.","explanation":"Comparison.","explanation_ar":"مقارنة.","dok":3,"skill":"compare","stage":"production"}]}],"game":{"name":"Compound Train","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Train coupler: two word cars roll in; the child couples them, hears the compound word and chooses its meaning. Correct trains leave the station with a whistle.","Teams get a set of word cars.","They join two cars to make a compound word.","They park it at the right station: one word (airport) or two words (bus stop).","A player explains the meaning using both parts.","Real word + correct station + meaning = 3 points."],"data":[]},"exit_quiz":[{"q":"Which word means *a trip from one place to another*?","answer":"journey","explanation":"Journey = trip.","explanation_ar":"رحلة.","options":["ticket","station","map","journey"],"dok":1,"skill":"vocabulary"},{"q":"A compound word is ___.","answer":"two smaller words joined together","explanation":"Compound = two words joined.","explanation_ar":"كلمتان مندمجتان.","options":["a word with a suffix","a very long name","two smaller words joined together","a word with no vowels"],"dok":1,"skill":"compound words"},{"q":"Which two words make *backpack*?","answer":"back + pack","explanation":"back + pack.","explanation_ar":"back + pack.","options":["back + pack","ba + ckpack","bag + pack","back + pick"],"dok":1,"skill":"compound words"},{"q":"Which word belongs to the *pass* family?","answer":"passenger","explanation":"pass → passenger.","explanation_ar":"passenger.","options":["plane","port","passenger","people"],"dok":2,"skill":"word families"},{"q":"Which sentence about traveling to Jeddah is correct?","answer":"We went to Jeddah by train.","explanation":"by + transport (no the).","explanation_ar":"by train.","options":["We went to Jeddah by train.","We went to Jeddah by the train.","We went to Jeddah with train.","We went to Jeddah on by train."],"dok":2,"skill":"grammar"},{"q":"*Who invented the bicycle?* *Invented* means ___.","answer":"made for the first time","explanation":"Invent = make something new.","explanation_ar":"اخترع.","options":["rode very fast","made for the first time","sold","broke"],"dok":1,"skill":"vocabulary"},{"q":"Which compound word names a road for fast cars?","answer":"highway","explanation":"high + way.","explanation_ar":"highway.","options":["railway","highway","airport","seaport"],"dok":2,"skill":"compound words"},{"q":"Which sentence compares two kinds of transport correctly?","answer":"The train is faster than the bus.","explanation":"fast → faster than.","explanation_ar":"faster than.","options":["The train is more fast than the bus.","The train is fastest than the bus.","The train is fast than the bus.","The train is faster than the bus."],"dok":2,"skill":"comparatives"},{"q":"How does splitting a compound word help you?","answer":"You can use the meanings of the two small words to understand the big word.","explanation":"Two parts → meaning.","explanation_ar":"معنى الجزأين يساعد على الفهم.","options":["It makes the word disappear.","You can use the meanings of the two small words to understand the big word.","It tells you the date.","It changes the word into a verb."],"dok":3,"skill":"strategy"},{"q":"*Seatbelt* is a compound word. What is it most likely for?","answer":"a belt on a seat that keeps you safe in a car","explanation":"seat + belt.","explanation_ar":"حزام المقعد للأمان.","options":["a belt on a seat that keeps you safe in a car","a belt for your pants","a seat on a train","a kind of ticket"],"dok":3,"skill":"apply"}],"images":[{"id":"IMG-RW-L03-U3-LS1-V01","prompt":"Picture for the word 'car': a family car on a highway"},{"id":"IMG-RW-L03-U3-LS1-V02","prompt":"Picture for the word 'bus': a school bus"},{"id":"IMG-RW-L03-U3-LS1-V03","prompt":"Picture for the word 'train': a high-speed train"},{"id":"IMG-RW-L03-U3-LS1-V04","prompt":"Picture for the word 'plane': a passenger plane taking off"},{"id":"IMG-RW-L03-U3-LS1-V05","prompt":"Picture for the word 'ship': a ship at a port"},{"id":"IMG-RW-L03-U3-LS1-V06","prompt":"Picture for the word 'bicycle': a boy riding a bicycle"},{"id":"IMG-RW-L03-U3-LS1-V07","prompt":"Picture for the word 'airport': an airport terminal with planes"},{"id":"IMG-RW-L03-U3-LS1-V08","prompt":"Picture for the word 'station': a modern train station"},{"id":"IMG-RW-L03-U3-LS1-V09","prompt":"Picture for the word 'ticket': a train ticket and a phone with a QR code"},{"id":"IMG-RW-L03-U3-LS1-V10","prompt":"Picture for the word 'passenger': passengers sitting on a train"},{"id":"IMG-RW-L03-U3-LS1-V11","prompt":"Picture for the word 'journey': a dotted path on a map from one city to another"},{"id":"IMG-RW-L03-U3-LS1-V12","prompt":"Picture for the word 'map': a map of Saudi Arabia"},{"id":"IMG-RW-L03-U3-LS1-V13","prompt":"Picture for the word 'fast': a speeding train with motion lines"},{"id":"IMG-RW-L03-U3-LS1-V14","prompt":"Picture for the word 'slow': a camel walking slowly"},{"id":"IMG-RW-L03-U3-LS1-V15","prompt":"Picture for the word 'transport': icons of a car, a train, a plane and a ship"},{"id":"IMG-RW-L03-U3-LS1-V16","prompt":"Picture for the word 'sequence': numbered cards 1, 2, 3 in a row"},{"id":"IMG-RW-L03-U3-LS1-V17","prompt":"Picture for the word 'invent': an inventor with a new machine and a light bulb"},{"id":"IMG-RW-L03-U3-LS1-01","prompt":"A map of Saudi Arabia with a camel, a car, a train, a plane and a ship."},{"id":"IMG-RW-L03-U3-LS1-02","prompt":"Two word blocks joining to make 'airport'."},{"id":"IMG-RW-L03-U3-LS1-03","prompt":"A word family tree for 'travel'."}],"audio":[{"id":"AUD-RW-L03-U3-LS1-V01","script":"car. We drove to Jeddah by car."},{"id":"AUD-RW-L03-U3-LS1-V02","script":"bus. The school bus comes at seven."},{"id":"AUD-RW-L03-U3-LS1-V03","script":"train. The train goes from Makkah to Madinah."},{"id":"AUD-RW-L03-U3-LS1-V04","script":"plane. The plane landed in Riyadh."},{"id":"AUD-RW-L03-U3-LS1-V05","script":"ship. The ship sailed across the Red Sea."},{"id":"AUD-RW-L03-U3-LS1-V06","script":"bicycle. Faris rides his bicycle in the park."},{"id":"AUD-RW-L03-U3-LS1-V07","script":"airport. We met Grandpa at the airport."},{"id":"AUD-RW-L03-U3-LS1-V08","script":"station. The train station is very modern."},{"id":"AUD-RW-L03-U3-LS1-V09","script":"ticket. Show your ticket to the driver."},{"id":"AUD-RW-L03-U3-LS1-V10","script":"passenger. The plane has 200 passengers."},{"id":"AUD-RW-L03-U3-LS1-V11","script":"journey. The journey took three hours."},{"id":"AUD-RW-L03-U3-LS1-V12","script":"map. Look at the map to find Taif."},{"id":"AUD-RW-L03-U3-LS1-V13","script":"fast. The train is very fast."},{"id":"AUD-RW-L03-U3-LS1-V14","script":"slow. Camels are slow but strong."},{"id":"AUD-RW-L03-U3-LS1-V15","script":"transport. Trains are a fast kind of transport."},{"id":"AUD-RW-L03-U3-LS1-V16","script":"sequence. Put the events in the right sequence."},{"id":"AUD-RW-L03-U3-LS1-V17","script":"invent. Who invented the bicycle?"},{"id":"AUD-RW-L03-U3-LS1-VID","script":"Pack your bags! Sami is going on a journey across Saudi Arabia! By car, by bus, by train, by plane, by ship – and by bicycle! At the airport and the station, passengers show their tickets. Fast or slow – every journey needs a map! Compound words: air + port = airport! rail + way = railway! suit + case = suitcase! Word families: travel, traveler, traveling, traveled! People invented new transport, one after another. Let's learn the sequence!"}]},{"id":"RW-L03-U3-LS2","title":"From Camels to Trains","lesson_type":"close_reading","objectives":["read an informational article of about 200 words about the history of transport in Arabia","compare the past and the present using time signal words (long ago, in 1908, today, now)","answer literal, inferential and evaluative questions with evidence"],"objectives_ar":["قراءة مقال معلوماتي من نحو 200 كلمة عن تاريخ النقل في جزيرة العرب.","المقارنة بين الماضي والحاضر باستخدام كلمات الإشارة الزمنية.","الإجابة عن أسئلة حرفية واستنتاجية وتقييمية مع الدليل."],"success_criteria":["I can find dates and time words in the article.","I can tell how travel was then and how it is now.","I can support my answers with numbers and facts from the text."],"success_criteria_ar":["أستطيع إيجاد التواريخ وكلمات الوقت في المقال.","أستطيع قول كيف كان السفر وكيف أصبح.","أستطيع دعم إجاباتي بالأرقام والحقائق من النص."],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"thousands","pos":"noun","ipa":"/ˈθaʊzəndz/","definition":"many groups of 1,000; a very large number","arabic":"آلاف","example":"For thousands of years, people used camels.","image_id":"IMG-RW-L03-U3-LS2-V01","audio_id":"AUD-RW-L03-U3-LS2-V01","tier":"core"},{"word":"carry","pos":"verb","ipa":"/ˈkæri/","definition":"to hold something and take it with you","arabic":"يحمل","example":"Camels carry heavy bags.","image_id":"IMG-RW-L03-U3-LS2-V02","audio_id":"AUD-RW-L03-U3-LS2-V02","tier":"core"},{"word":"railway","pos":"noun","ipa":"/ˈreɪlweɪ/","definition":"the tracks that trains run on; a train system","arabic":"سكة حديد","example":"The Hejaz Railway reached Madinah in 1908.","image_id":"IMG-RW-L03-U3-LS2-V03","audio_id":"AUD-RW-L03-U3-LS2-V03","tier":"core"},{"word":"pilgrim","pos":"noun","ipa":"/ˈpɪlɡrɪm/","definition":"a person who travels to a holy place","arabic":"حاج","example":"Pilgrims travel to Makkah.","image_id":"IMG-RW-L03-U3-LS2-V04","audio_id":"AUD-RW-L03-U3-LS2-V04","tier":"core"},{"word":"goods","pos":"noun","ipa":"/ɡʊdz/","definition":"things that people buy and sell","arabic":"بضائع","example":"Trains carried goods like rice and dates.","image_id":"IMG-RW-L03-U3-LS2-V05","audio_id":"AUD-RW-L03-U3-LS2-V05","tier":"core"},{"word":"highway","pos":"noun","ipa":"/ˈhaɪweɪ/","definition":"a big, fast road between cities","arabic":"طريق سريع","example":"We drove on the highway to Riyadh.","image_id":"IMG-RW-L03-U3-LS2-V06","audio_id":"AUD-RW-L03-U3-LS2-V06","tier":"core"},{"word":"history","pos":"noun","ipa":"/ˈhɪstəri/","definition":"things that happened in the past","arabic":"التاريخ","example":"We learned the history of transport.","image_id":"IMG-RW-L03-U3-LS2-V07","audio_id":"AUD-RW-L03-U3-LS2-V07","tier":"core"}],"explanation":{"text":"Some articles tell how something **changed over time**. They compare **then** (the past) and **now** (the present).\n\nLook for **time signal words**: **for thousands of years, long ago, in 1908, about 100 years ago, later** (past) and **today, now** (present).\n\nAsk: **How was it then? How is it now? What changed? What stayed the same?** Use **numbers** in the text as evidence (two weeks → less than three hours).","examples":["Then: **People traveled across the desert by camel.**","Now: **People take the high-speed train or fly.**","Then: **Makkah to Madinah took about two weeks.** → Now: **less than three hours**.","Time words for the past: **For thousands of years… In 1908… About one hundred years ago… Later…**","Time words for the present: **Today… Now…**","Change: **Trains carried pilgrims much faster than camels.**","Number evidence: **300 kilometers an hour**.","Stayed the same: **Many families still keep camels.**","Compare with *but*: **Travel was slow then, but it is very fast now.**"],"common_errors":["✗ In the past people travel by camel. → ✓ In the past, people traveled by camel. (Past events → **past tense** (traveled).)","✗ Now the journey took three hours. → ✓ Now the journey takes less than three hours. (Present → **present tense** (takes).)","✗ In 1908 a railway reach Madinah. → ✓ In 1908, a railway reached Madinah. (Past → **reached**; comma after the date.)","✗ Trains are more faster. → ✓ Trains are faster. (Don't use **more** with **-er**.)","✗ Answering 'very long' for 'How long did it take?' → ✓ It took about two weeks. (Use the **number** from the text.)","✗ The camels is slow. → ✓ Camels are slow. (Many camels → **are**.)"],"arabic":"بعض المقالات تحكي كيف تغيّر شيء مع الزمن، فتقارن بين الماضي (then) والحاضر (now).\n\nابحث عن كلمات الإشارة الزمنية: for thousands of years, in 1908, about 100 years ago, later للماضي، وtoday, now للحاضر.\n\nاسأل: كيف كان؟ كيف أصبح؟ ماذا تغيّر؟ ماذا بقي؟ واستخدم الأرقام في النص دليلًا.\n\nانتبه لزمن الفعل: الماضي traveled, reached، والحاضر takes, can travel."},"video":{"script":[{"time":"00:00–00:20","narration":"Grandpa Saleh's grandfather traveled by camel. Sami travels by train! What changed?","on_screen":"Then ⏳ and Now ⚡","visual":"Split screen: an old caravan and a modern high-speed train."},{"time":"00:20–01:40","narration":"From Camels to Trains. For thousands of years, people in Arabia traveled across the desert by camel…","on_screen":"(article, section by section)","visual":"Animated history: caravan, the old Hejaz steam train at Madinah, the first cars, highways, planes, the Haramain train."},{"time":"01:40–02:15","narration":"Look for time words: in 1908… about one hundred years ago… today… now!","on_screen":"Past words · Present words","visual":"Time words fly onto a timeline in two colors."},{"time":"02:15–02:45","narration":"Then: two weeks. Now: less than three hours! Numbers are great evidence.","on_screen":"2 weeks → < 3 hours","visual":"A big calendar shrinks into a small clock."},{"time":"02:45–03:00","narration":"But some things stay the same. Many families still keep camels!","on_screen":"What stayed the same?","visual":"Sami pats a camel at Grandpa's farm."}],"captions_ar":["جدّ الجد صالح سافر على الجمل، وسامي يسافر بالقطار! ما الذي تغيّر؟","من الجمال إلى القطارات: لآلاف السنين سافر الناس في جزيرة العرب عبر الصحراء على الجمال…","ابحث عن كلمات الوقت: في 1908… قبل نحو مئة عام… اليوم… الآن!","في الماضي أسبوعان، والآن أقل من ثلاث ساعات! الأرقام دليل رائع.","لكن بعض الأشياء لم تتغير؛ فكثير من العائلات ما زالت تربي الجمال!"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Grandpa Saleh (memories): slow, warm elderly voice."},"texts":[{"type":"reading","title":"From Camels to Trains","body":"For thousands of years, people in Arabia traveled across the desert by camel. Camels could carry heavy bags and walk for days without water. A journey from Makkah to Madinah took about two weeks!\n\n**The First Railway**\n\nIn 1908, a new railway reached Madinah. It was called the Hejaz Railway. Trains carried pilgrims and goods much faster than camels. Today, you can still visit the old train station in Madinah.\n\n**Cars and Planes**\n\nAbout one hundred years ago, the first cars came to Arabia. Later, people built long highways across the country. About eighty years ago, the first passenger planes began to fly between Saudi cities. Now, people can fly from Riyadh to Jeddah in less than two hours.\n\n**A Super-Fast Train**\n\nIn 2018, the Haramain High-Speed Railway opened. Its trains can travel at 300 kilometers an hour! Now, the journey from Makkah to Madinah takes less than three hours.\n\nTransport has changed a lot. But many families still keep camels and remember how their grandparents traveled long ago.","word_count":169,"audio_id":"AUD-RW-L03-U3-LS2-T1","id":"TXT-RW-L03-U3-LS2-1","genre":"informational","role":"main","difficulty":"350L–500L","glossary":[{"word":"pilgrims","definition":"people who travel to a holy place, like Makkah","arabic":"حُجّاج"},{"word":"goods","definition":"things that people buy and sell","arabic":"بضائع"},{"word":"high-speed","definition":"very, very fast","arabic":"فائق السرعة"}]}],"activities":[{"id":"RW-L03-U3-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the article. Choose the answer.","instructions_ar":"اقرأ المقال واختر الإجابة.","items":[{"q":"How did people in Arabia travel for thousands of years?","answer":"by camel","explanation":"Paragraph 1.","explanation_ar":"على الجمال.","options":["by camel","by plane","by bicycle","by ship only"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"How long did a camel journey from Makkah to Madinah take?","answer":"about two weeks","explanation":"Paragraph 1.","explanation_ar":"نحو أسبوعين.","options":["two hours","one day","one year","about two weeks"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"When did the Hejaz Railway reach Madinah?","answer":"in 1908","explanation":"The First Railway.","explanation_ar":"عام 1908.","options":["in 2018","about eighty years ago","in 1908","last year"],"dok":1,"skill":"key details: when","stage":"controlled"},{"q":"What did the first trains carry?","answer":"pilgrims and goods","explanation":"The First Railway.","explanation_ar":"الحجاج والبضائع.","options":["only cars","only camels","pilgrims and goods","planes"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"How fast can the Haramain trains travel?","answer":"300 kilometers an hour","explanation":"A Super-Fast Train.","explanation_ar":"300 كم في الساعة.","options":["30 kilometers an hour","300 kilometers an hour","3 kilometers an hour","3,000 kilometers an hour"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"How long does a flight from Riyadh to Jeddah take now?","answer":"less than two hours","explanation":"Cars and Planes.","explanation_ar":"أقل من ساعتين.","options":["about two weeks","less than three hours by camel","one day","less than two hours"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L03-U3-LS2-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Then and now. Choose.","instructions_ar":"الماضي والحاضر: اختر.","items":[{"q":"Which time words tell about the PAST?","answer":"about one hundred years ago","explanation":"ago = past.","explanation_ar":"قبل مئة عام.","options":["now","about one hundred years ago","today","these days"],"dok":1,"skill":"time signal words","stage":"guided"},{"q":"Which sentence tells about the PRESENT?","answer":"Now, the journey from Makkah to Madinah takes less than three hours.","explanation":"Now = present.","explanation_ar":"الحاضر.","options":["Now, the journey from Makkah to Madinah takes less than three hours.","For thousands of years, people traveled by camel.","In 1908, a new railway reached Madinah.","About one hundred years ago, the first cars came."],"dok":1,"skill":"time signal words","stage":"guided"},{"q":"Which came FIRST in Arabia?","answer":"the Hejaz Railway","explanation":"1908 is the earliest date.","explanation_ar":"سكة حديد الحجاز.","options":["the first passenger planes","the Haramain High-Speed Railway","the Hejaz Railway","long highways"],"dok":2,"skill":"sequence","stage":"guided"},{"q":"Which detail shows travel became MUCH faster?","answer":"two weeks by camel → less than three hours by train","explanation":"Compare the two numbers.","explanation_ar":"مقارنة الرقمين.","options":["Camels carry heavy bags.","two weeks by camel → less than three hours by train","You can visit the old station.","Many families keep camels."],"dok":2,"skill":"evidence","stage":"guided"},{"q":"What has STAYED THE SAME, says the article?","answer":"Many families still keep camels.","explanation":"Stayed the same = still.","explanation_ar":"ما زالت العائلات تربي الجمال.","options":["Trains carry pilgrims at 300 km an hour.","Planes fly between cities.","Highways go across the country.","Many families still keep camels."],"dok":2,"skill":"compare","stage":"guided"},{"q":"Why were camels good for desert journeys long ago?","answer":"They could carry heavy bags and walk for days without water.","explanation":"Paragraph 1.","explanation_ar":"يحملون أثقالًا ويمشون أيامًا دون ماء.","options":["They could carry heavy bags and walk for days without water.","They were very fast.","They could fly.","They needed a lot of water."],"dok":2,"skill":"cause and effect","stage":"guided"}]},{"id":"RW-L03-U3-LS2-A3","type":"highlight","stage":"freer","instructions":"Find the evidence: Find the evidence.","instructions_ar":"ابحث عن الدليل.","items":[{"q":"Underline the sentence that tells what you can still visit today.","answer":"Today, you can still visit the old train station in Madinah.","explanation":"Today + still.","explanation_ar":"اليوم + ما زال.","evidence":"Today, you can still visit the old train station in Madinah.","text_id":"TXT-RW-L03-U3-LS2-1","dok":1,"skill":"evidence","stage":"freer","sentences":["For thousands of years, people in Arabia traveled across the desert by camel.","Camels could carry heavy bags and walk for days without water.","A journey from Makkah to Madinah took about two weeks!","**The First Railway**","In 1908, a new railway reached Madinah.","It was called the Hejaz Railway.","Trains carried pilgrims and goods much faster than camels.","Today, you can still visit the old train station in Madinah.","**Cars and Planes**","About one hundred years ago, the first cars came to Arabia.","Later, people built long highways across the country.","About eighty years ago, the first passenger planes began to fly between Saudi cities.","Now, people can fly from Riyadh to Jeddah in less than two hours.","**A Super-Fast Train**","In 2018, the Haramain High-Speed Railway opened.","Its trains can travel at 300 kilometers an hour!","Now, the journey from Makkah to Madinah takes less than three hours.","Transport has changed a lot.","But many families still keep camels and remember how their grandparents traveled long ago."]},{"q":"Underline the sentence that compares trains and camels.","answer":"Trains carried pilgrims and goods much faster than camels.","explanation":"faster than.","explanation_ar":"أسرع من.","evidence":"Trains carried pilgrims and goods much faster than camels.","text_id":"TXT-RW-L03-U3-LS2-1","dok":2,"skill":"evidence","stage":"freer","sentences":["For thousands of years, people in Arabia traveled across the desert by camel.","Camels could carry heavy bags and walk for days without water.","A journey from Makkah to Madinah took about two weeks!","**The First Railway**","In 1908, a new railway reached Madinah.","It was called the Hejaz Railway.","Trains carried pilgrims and goods much faster than camels.","Today, you can still visit the old train station in Madinah.","**Cars and Planes**","About one hundred years ago, the first cars came to Arabia.","Later, people built long highways across the country.","About eighty years ago, the first passenger planes began to fly between Saudi cities.","Now, people can fly from Riyadh to Jeddah in less than two hours.","**A Super-Fast Train**","In 2018, the Haramain High-Speed Railway opened.","Its trains can travel at 300 kilometers an hour!","Now, the journey from Makkah to Madinah takes less than three hours.","Transport has changed a lot.","But many families still keep camels and remember how their grandparents traveled long ago."]},{"q":"Why did the writer use headings like *The First Railway* and *Cars and Planes*?","answer":"to show the changes in time order, one part at a time","explanation":"Headings organize the history.","explanation_ar":"لعرض التغيّرات بترتيب زمني.","options":["to tell a story with a problem","to list new words","to ask questions","to show the changes in time order, one part at a time"],"dok":2,"skill":"text structure","stage":"freer"},{"q":"What is the main idea of *From Camels to Trains*?","answer":"Travel in Arabia changed from slow camels to very fast trains and planes.","explanation":"It covers the whole article.","explanation_ar":"تغيّر السفر من الجمال البطيئة إلى القطارات والطائرات السريعة.","options":["Camels can walk for days.","Planes are better than trains.","Travel in Arabia changed from slow camels to very fast trains and planes.","Madinah has an old station."],"dok":3,"skill":"main idea","stage":"freer"}]},{"id":"RW-L03-U3-LS2-A4","type":"open","stage":"production","instructions":"Writing: Compare and evaluate.","instructions_ar":"قارن وقيّم.","items":[{"q":"Write one sentence comparing then and now. Use *but*.","answer":"Long ago, people traveled by camel, but now they take fast trains.","explanation":"Then…, but now…","explanation_ar":"Then…, but now…","dok":2,"skill":"compare","stage":"production"},{"q":"Use numbers from the text to show how much faster travel is now.","answer":"A camel journey took about two weeks, but the train takes less than three hours.","explanation":"Two numbers.","explanation_ar":"رقمان.","dok":2,"skill":"evidence","stage":"production"},{"q":"Why do you think many families still keep camels?","answer":"They love camels and want to remember how their grandparents lived.","explanation":"Inference + reason.","explanation_ar":"استنتاج + سبب.","dok":3,"skill":"inference","stage":"production"},{"q":"Which change in transport do you think helped people the most? Why?","answer":"The high-speed train helped the most because pilgrims can travel safely and quickly.","explanation":"Opinion + reason.","explanation_ar":"رأي + سبب.","dok":3,"skill":"evaluate","stage":"production"}]},{"id":"RW-L03-U3-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"From Camels to Trains\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “From Camels to Trains”.","answer":"169 words","title":"From Camels to Trains","body":"For thousands of years, people in Arabia traveled across the desert by camel. Camels could carry heavy bags and walk for days without water. A journey from Makkah to Madinah took about two weeks!\n\n**The First Railway**\n\nIn 1908, a new railway reached Madinah. It was called the Hejaz Railway. Trains carried pilgrims and goods much faster than camels. Today, you can still visit the old train station in Madinah.\n\n**Cars and Planes**\n\nAbout one hundred years ago, the first cars came to Arabia. Later, people built long highways across the country. About eighty years ago, the first passenger planes began to fly between Saudi cities. Now, people can fly from Riyadh to Jeddah in less than two hours.\n\n**A Super-Fast Train**\n\nIn 2018, the Haramain High-Speed Railway opened. Its trains can travel at 300 kilometers an hour! Now, the journey from Makkah to Madinah takes less than three hours.\n\nTransport has changed a lot. But many families still keep camels and remember how their grandparents traveled long ago.","words":169,"limit":159}],"time_limit_sec":159}],"game":{"name":"Then or Now?","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Time travel: a fact card floats in a time machine; the child sends it to the past or the present and taps the time word. Correct answers move the machine forward in history.","Place the THEN sign on one side of the room and the NOW sign on the other.","The teacher reads a fact card.","Students walk to THEN or NOW.","One student in the right group says the time word or verb tense that helped.","Correct group = 1 point for each student there; correct clue = bonus point."],"data":[]},"exit_quiz":[{"q":"What is *From Camels to Trains* mostly about?","answer":"how transport in Arabia changed over time","explanation":"History of transport.","explanation_ar":"كيف تغيّر النقل.","options":["how transport in Arabia changed over time","how to ride a camel","a family trip to Jeddah","how planes are built"],"dok":1,"skill":"main topic"},{"q":"Which word tells about the present?","answer":"today","explanation":"today = present.","explanation_ar":"today.","options":["today","ago","long ago","in 1908"],"dok":1,"skill":"time signal words"},{"q":"*Trains carried pilgrims and goods.* *Goods* are ___.","answer":"things people buy and sell","explanation":"Goods = things to sell.","explanation_ar":"بضائع.","options":["good people","train tickets","kinds of camels","things people buy and sell"],"dok":1,"skill":"vocabulary in context"},{"q":"What is the Hejaz Railway?","answer":"an old railway that reached Madinah in 1908","explanation":"The First Railway section.","explanation_ar":"سكة حديد قديمة.","options":["a new highway","an old railway that reached Madinah in 1908","an airport in Riyadh","a kind of camel"],"dok":1,"skill":"key details"},{"q":"Which sentence about the past uses the past tense correctly?","answer":"In 1908, a new railway reached Madinah.","explanation":"Past → reached.","explanation_ar":"الماضي.","options":["In 1908, a new railway reaches Madinah.","In 1908, a new railway reach Madinah.","In 1908, a new railway reached Madinah.","In 1908, a new railway will reach Madinah."],"dok":2,"skill":"grammar"},{"q":"Put these in time order: (1) the first passenger planes (2) camel caravans (3) the Haramain train (4) the Hejaz Railway","answer":"2, 4, 1, 3","explanation":"camels → 1908 railway → planes → 2018 train.","explanation_ar":"2، 4، 1، 3.","options":["1, 2, 3, 4","4, 2, 1, 3","2, 4, 1, 3","2, 1, 4, 3"],"dok":2,"skill":"sequence"},{"q":"How many times faster is the train journey than the camel journey, roughly?","answer":"more than 100 times faster","explanation":"Two weeks ≈ 336 hours vs. less than 3 hours.","explanation_ar":"أسرع بأكثر من مئة مرة.","options":["about 2 times faster","more than 100 times faster","the same speed","slower"],"dok":3,"skill":"analyze numbers"},{"q":"Why does the article end by talking about camels again?","answer":"to show that people still remember the past","explanation":"It connects past and present.","explanation_ar":"ليُظهر أن الناس ما زالوا يتذكرون الماضي.","options":["to say trains are slow","to start a new topic about food","to show that people still remember the past","to describe the weather"],"dok":3,"skill":"author's purpose"},{"q":"Which detail is an example of *goods*?","answer":"rice and dates","explanation":"Things to buy and sell.","explanation_ar":"الأرز والتمر.","options":["pilgrims","highways","tickets","rice and dates"],"dok":2,"skill":"apply"},{"q":"Which question is answered by the heading *A Super-Fast Train*?","answer":"How fast is the Haramain train?","explanation":"That section tells the speed.","explanation_ar":"كم سرعة قطار الحرمين؟","options":["Who invented the camel saddle?","How fast is the Haramain train?","When did cars come to Arabia?","What did pilgrims eat?"],"dok":2,"skill":"text features"}],"images":[{"id":"IMG-RW-L03-U3-LS2-V01","prompt":"Picture for the word 'thousands': a big number 1,000 with many dots"},{"id":"IMG-RW-L03-U3-LS2-V02","prompt":"Picture for the word 'carry': a camel carrying bags"},{"id":"IMG-RW-L03-U3-LS2-V03","prompt":"Picture for the word 'railway': an old steam train on desert tracks"},{"id":"IMG-RW-L03-U3-LS2-V04","prompt":"Picture for the word 'pilgrim': pilgrims in white walking"},{"id":"IMG-RW-L03-U3-LS2-V05","prompt":"Picture for the word 'goods': boxes and sacks on a train car"},{"id":"IMG-RW-L03-U3-LS2-V06","prompt":"Picture for the word 'highway': a long highway through the desert"},{"id":"IMG-RW-L03-U3-LS2-V07","prompt":"Picture for the word 'history': an old photo and a timeline"},{"id":"IMG-RW-L03-U3-LS2-01","prompt":"A camel caravan and an old steam train at Madinah station."},{"id":"IMG-RW-L03-U3-LS2-02","prompt":"A high-speed train, a plane and a highway."},{"id":"IMG-RW-L03-U3-LS2-03","prompt":"Two weeks by camel compared with under three hours by train."}],"audio":[{"id":"AUD-RW-L03-U3-LS2-V01","script":"thousands. For thousands of years, people used camels."},{"id":"AUD-RW-L03-U3-LS2-V02","script":"carry. Camels carry heavy bags."},{"id":"AUD-RW-L03-U3-LS2-V03","script":"railway. The Hejaz Railway reached Madinah in 1908."},{"id":"AUD-RW-L03-U3-LS2-V04","script":"pilgrim. Pilgrims travel to Makkah."},{"id":"AUD-RW-L03-U3-LS2-V05","script":"goods. Trains carried goods like rice and dates."},{"id":"AUD-RW-L03-U3-LS2-V06","script":"highway. We drove on the highway to Riyadh."},{"id":"AUD-RW-L03-U3-LS2-V07","script":"history. We learned the history of transport."},{"id":"AUD-RW-L03-U3-LS2-T1","script":"For thousands of years, people in Arabia traveled across the desert by camel. Camels could carry heavy bags and walk for days without water. A journey from Makkah to Madinah took about two weeks! **The First Railway** In 1908, a new railway reached Madinah. It was called the Hejaz Railway. Trains carried pilgrims and goods much faster than camels. Today, you can still visit the old train station in Madinah. **Cars and Planes** About one hundred years ago, the first cars came to Arabia. Later, people built long highways across the country. About eighty years ago, the first passenger planes began to fly between Saudi cities. Now, people can fly from Riyadh to Jeddah in less than two hours. **A Super-Fast Train** In 2018, the Haramain High-Speed Railway opened. Its trains can travel at 300 kilometers an hour! Now, the journey from Makkah to Madinah takes less than three hours. Transport has changed a lot. But many families still keep camels and remember how their grandparents traveled long ago."},{"id":"AUD-RW-L03-U3-LS2-VID","script":"Grandpa Saleh's grandfather traveled by camel. Sami travels by train! What changed? From Camels to Trains. For thousands of years, people in Arabia traveled across the desert by camel… Look for time words: in 1908… about one hundred years ago… today… now! Then: two weeks. Now: less than three hours! Numbers are great evidence. But some things stay the same. Many families still keep camels!"}]},{"id":"RW-L03-U3-LS3","title":"Sequence on a timeline: \"How to Pack for a Trip\"","lesson_type":"strategy_paired_text","objectives":["put events and steps in the right sequence using dates and time words","show the sequence of a history article and a how-to text on a timeline","explain why the order matters (what happens if you change it)"],"objectives_ar":["ترتيب الأحداث والخطوات تسلسليًا باستخدام التواريخ وكلمات الوقت.","عرض تسلسل مقال تاريخي ونص إرشادي على خط زمني.","شرح أهمية الترتيب (ماذا يحدث إذا غيّرناه)."],"success_criteria":["I can find dates and time words that show order.","I can put events on a timeline from first to last.","I can explain why the sequence matters."],"success_criteria_ar":["أستطيع إيجاد التواريخ وكلمات الوقت التي تُظهر الترتيب.","أستطيع وضع الأحداث على خط زمني من الأول إلى الأخير.","أستطيع شرح أهمية التسلسل."],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"pack","pos":"verb","ipa":"/pæk/","definition":"to put things in a bag or suitcase for a trip","arabic":"يحزم (الأمتعة)","example":"Pack your suitcase the night before.","image_id":"IMG-RW-L03-U3-LS3-V01","audio_id":"AUD-RW-L03-U3-LS3-V01","tier":"core"},{"word":"suitcase","pos":"noun","ipa":"/ˈsutkeɪs/","definition":"a big bag with a handle for clothes on a trip","arabic":"حقيبة سفر","example":"My suitcase is blue.","image_id":"IMG-RW-L03-U3-LS3-V02","audio_id":"AUD-RW-L03-U3-LS3-V02","tier":"core"},{"word":"list","pos":"noun","ipa":"/lɪst/","definition":"words written one under the other","arabic":"قائمة","example":"Make a list of what you need.","image_id":"IMG-RW-L03-U3-LS3-V03","audio_id":"AUD-RW-L03-U3-LS3-V03","tier":"core"},{"word":"heavy","pos":"adjective","ipa":"/ˈhɛvi/","definition":"weighing a lot; hard to lift","arabic":"ثقيل","example":"Put heavy things at the bottom.","image_id":"IMG-RW-L03-U3-LS3-V04","audio_id":"AUD-RW-L03-U3-LS3-V04","tier":"core"},{"word":"backpack","pos":"noun","ipa":"/ˈbækpæk/","definition":"a bag you carry on your back","arabic":"حقيبة ظهر","example":"Put your ticket in your backpack.","image_id":"IMG-RW-L03-U3-LS3-V05","audio_id":"AUD-RW-L03-U3-LS3-V05","tier":"core"},{"word":"timeline","pos":"noun","ipa":"/ˈtaɪmlaɪn/","definition":"a line that shows events in the order they happened","arabic":"خط زمني","example":"We made a timeline of transport.","image_id":"IMG-RW-L03-U3-LS3-V06","audio_id":"AUD-RW-L03-U3-LS3-V06","tier":"core"},{"word":"before","pos":"preposition","ipa":"/bɪˈfɔr/","definition":"earlier than","arabic":"قبل","example":"Wash your clothes three days before the trip.","image_id":"IMG-RW-L03-U3-LS3-V07","audio_id":"AUD-RW-L03-U3-LS3-V07","tier":"core"}],"explanation":{"text":"**Sequence** is the **order** in which things happen. Writers show sequence with **dates** (1908, 2018), **time phrases** (one week before, the night before, about 100 years ago) and **order words** (first, then, finally).\n\nA **timeline** is a line that shows events from **first** (left) to **last** (right). Put the **earliest** event on the left. Write the **date or time** above the line and the **event** below it.\n\nAsk: **What happened first? next? last? What would happen if the order changed?** In a how-to text, the wrong order can cause problems!","examples":["History timeline: **thousands of years ago** → camels.","→ **1908** → the Hejaz Railway reaches Madinah.","→ **about 100 years ago** → the first cars come to Arabia.","→ **about 80 years ago** → the first passenger planes.","→ **2018** → the Haramain High-Speed Railway opens.","Packing timeline: **one week before** → make a list → **three days before** → wash clothes → **the night before** → pack the suitcase → **morning** → check the list.","Inside one step: **First,** heavy things at the bottom → **Then,** clothes on top → **Finally,** small things in the side pocket.","Why order matters: if you put shoes **on top** of your clothes, your clothes will be crushed and dirty.","Signal words: *before, after, then, later, finally, today, now*."],"common_errors":["✗ Putting the newest event on the left. → ✓ Put the **earliest** event on the **left**. (Timelines go from first to last.)","✗ 2018 came before 1908. → ✓ 1908 came before 2018. (Smaller year number = earlier.)","✗ Packing the suitcase before making the list. → ✓ Make the list **first** (one week before). (Follow the time phrases.)","✗ The night before, wash your clothes. → ✓ Three days before, wash your clothes. (Check the right time for each step.)","✗ First put shoes at the bottom. → ✓ First, put shoes at the bottom. (Comma after **First**.)","✗ I pack my bag before one week. → ✓ I pack my bag one week before the trip. (Say **one week before**.)"],"arabic":"التسلسل (sequence) هو ترتيب حدوث الأشياء، ويُظهره الكاتب بالتواريخ (1908، 2018) وعبارات الوقت (one week before) وكلمات الترتيب (first, then, finally).\n\nالخط الزمني خط يعرض الأحداث من الأول (يسارًا) إلى الأخير (يمينًا)، والتاريخ أو الوقت فوق الخط والحدث تحته.\n\nاسأل: ماذا حدث أولًا؟ ثم؟ وأخيرًا؟ وماذا يحدث لو تغيّر الترتيب؟ ففي النص الإرشادي قد يسبب الترتيب الخطأ مشكلات!\n\nالسنة الأصغر رقمًا أقدم: 1908 قبل 2018."},"video":{"script":[{"time":"00:00–00:20","narration":"Everything happens in order – history AND packing! Let's make timelines.","on_screen":"Sequence ➡️ Timeline","visual":"A long line rolls out across the screen."},{"time":"00:20–00:55","narration":"Camels… 1908 railway… first cars… first planes… 2018 high-speed train!","on_screen":"History timeline","visual":"Pictures pop onto the line from left to right with dates above."},{"time":"00:55–01:55","narration":"How to Pack for a Trip. One week before: make a list…","on_screen":"(how-to text)","visual":"Lama and Sami follow each step; a calendar flips from 'one week before' to 'the morning of the trip'."},{"time":"01:55–02:30","narration":"Oops! Lama put the shoes on top of her clothes. Why does the order matter?","on_screen":"Order matters!","visual":"Squashed clothes under muddy shoes; Lama laughs and fixes it."},{"time":"02:30–03:00","narration":"Earliest on the left, latest on the right. Dates above, events below!","on_screen":"How to draw a timeline","visual":"A hand draws a timeline and labels it neatly."}],"captions_ar":["كل شيء يحدث بترتيب… التاريخ وحزم الأمتعة أيضًا! لنصنع خطوطًا زمنية.","الجمال… سكة حديد 1908… أول السيارات… أول الطائرات… قطار 2018 السريع!","كيف تحزم أمتعتك لرحلة: قبل أسبوع اكتب قائمة…","أوه! وضعت لمى الأحذية فوق ملابسها. لماذا يهم الترتيب؟","الأقدم يسارًا والأحدث يمينًا، والتواريخ فوق الخط والأحداث تحته!"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Lama (Sami's little sister) packs with Sami's help – giggly and curious."},"texts":[{"type":"reading","title":"How to Pack for a Trip","body":"Packing is easy when you follow the steps in the right order.\n\n**One week before:** Make a list of what you need: clothes, shoes, a toothbrush and a book for the journey.\n\n**Three days before:** Wash your favorite clothes so they are clean and ready.\n\n**The night before:** First, put heavy things like shoes at the bottom of your suitcase. Then, fold your clothes and put them on top. Finally, put your toothbrush and other small things in a side pocket.\n\n**On the morning of the trip:** Check your list one more time. Put your ticket, a snack and your book in your backpack.\n\nNow you are ready to go. Have a great journey!","word_count":114,"audio_id":"AUD-RW-L03-U3-LS3-T1","id":"TXT-RW-L03-U3-LS3-1","genre":"procedural","role":"paired","difficulty":"350L–500L","glossary":[{"word":"pack","definition":"put things in a bag or suitcase for a trip","arabic":"يحزم الأمتعة"},{"word":"heavy","definition":"weighing a lot; hard to lift","arabic":"ثقيل"},{"word":"side pocket","definition":"a small pocket on the side of a bag","arabic":"جيب جانبي"}]}],"activities":[{"id":"RW-L03-U3-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read *How to Pack for a Trip*. Choose the answer.","instructions_ar":"اقرأ النص واختر الإجابة.","items":[{"q":"What should you do one week before the trip?","answer":"make a list of what you need","explanation":"One week before.","explanation_ar":"اكتب قائمة.","options":["wash your clothes","pack your suitcase","check your ticket","make a list of what you need"],"dok":1,"skill":"sequence","text_id":"TXT-RW-L03-U3-LS3-1","stage":"controlled"},{"q":"When should you wash your favorite clothes?","answer":"three days before","explanation":"Three days before.","explanation_ar":"قبل ثلاثة أيام.","options":["one week before","three days before","the night before","on the morning of the trip"],"dok":1,"skill":"sequence","stage":"controlled"},{"q":"What goes at the bottom of the suitcase?","answer":"heavy things like shoes","explanation":"The night before: First…","explanation_ar":"الأشياء الثقيلة.","options":["heavy things like shoes","your toothbrush","your ticket","your book"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Where do the toothbrush and small things go?","answer":"in a side pocket","explanation":"Finally, … side pocket.","explanation_ar":"في الجيب الجانبي.","options":["at the bottom","in your shoes","in your hand","in a side pocket"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What goes in your backpack on the morning of the trip?","answer":"your ticket, a snack and your book","explanation":"On the morning of the trip.","explanation_ar":"التذكرة والوجبة والكتاب.","options":["your ticket, a snack and your book","your shoes","all your clothes","the suitcase"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What is the LAST step in the text?","answer":"Check your list and put your ticket in your backpack.","explanation":"The morning of the trip comes last.","explanation_ar":"التحقق من القائمة.","options":["Make a list.","Wash your clothes.","Check your list and put your ticket in your backpack.","Put heavy things at the bottom."],"dok":1,"skill":"sequence","stage":"controlled"}]},{"id":"RW-L03-U3-LS3-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Timelines. Choose.","instructions_ar":"الخطوط الزمنية: اختر.","items":[{"q":"On a timeline, where does the EARLIEST event go?","answer":"on the left","explanation":"First = left.","explanation_ar":"على اليسار.","options":["on the right","in the middle","on the left","under the title"],"dok":1,"skill":"timelines","stage":"guided"},{"q":"Which year comes first on a timeline?","answer":"1908","explanation":"Smallest year = earliest.","explanation_ar":"1908.","options":["2018","2026","1946","1908"],"dok":1,"skill":"dates","stage":"guided"},{"q":"Which event belongs right AFTER the Hejaz Railway on the history timeline?","answer":"the first cars came to Arabia","explanation":"1908 → about 100 years ago.","explanation_ar":"أول السيارات.","options":["the first cars came to Arabia","camel caravans","the Haramain train opened","the first passenger planes"],"dok":2,"skill":"sequence","stage":"guided"},{"q":"Which time phrase tells the EARLIEST packing step?","answer":"one week before","explanation":"One week is earliest.","explanation_ar":"قبل أسبوع.","options":["the night before","on the morning of the trip","three days before","one week before"],"dok":2,"skill":"time phrases","stage":"guided"},{"q":"What could happen if you put shoes on top of your clothes?","answer":"Your clothes could be crushed and dirty.","explanation":"Order matters.","explanation_ar":"تتسخ الملابس وتتجعد.","options":["Your shoes will fly away.","Your clothes could be crushed and dirty.","Your ticket will get lost.","Nothing at all."],"dok":2,"skill":"cause and effect","stage":"guided"},{"q":"How is the packing text like the history article?","answer":"Both use time words to show the order of events.","explanation":"Sequence in both.","explanation_ar":"كلاهما يستخدم كلمات الوقت.","options":["Both are about camels.","Both have a problem and a solution.","Both use time words to show the order of events.","Both are poems."],"dok":3,"skill":"compare texts","stage":"guided"}]},{"id":"RW-L03-U3-LS3-A3","type":"organizer","stage":"freer","instructions":"Organizer: Complete the packing timeline.","instructions_ar":"أكمل الخط الزمني للحزم.","items":[{"q":"Point 1: time + step.","answer":"One week before – make a list of what you need.","explanation":"Earliest step.","explanation_ar":"أقدم خطوة.","dok":1,"skill":"timelines","stage":"freer"},{"q":"Point 2: time + step.","answer":"Three days before – wash your favorite clothes.","explanation":"Second step.","explanation_ar":"الخطوة الثانية.","dok":1,"skill":"timelines","stage":"freer"},{"q":"Point 3: time + the three packing actions in order.","answer":"The night before – heavy things at the bottom, then clothes, then small things in the side pocket.","explanation":"Three actions in order.","explanation_ar":"ثلاثة أفعال بالترتيب.","dok":2,"skill":"timelines","stage":"freer"},{"q":"Point 4: time + step.","answer":"On the morning of the trip – check the list; put the ticket, snack and book in the backpack.","explanation":"Last step.","explanation_ar":"الخطوة الأخيرة.","dok":1,"skill":"timelines","stage":"freer"}]},{"id":"RW-L03-U3-LS3-A4","type":"open","stage":"production","instructions":"Writing: Sequence and explain.","instructions_ar":"رتّب واشرح.","items":[{"q":"Write three events from *From Camels to Trains* in time order with dates or time phrases.","answer":"In 1908, the railway reached Madinah. About 80 years ago, planes began to fly. In 2018, the high-speed train opened.","explanation":"Three events in order.","explanation_ar":"ثلاثة أحداث مرتبة.","dok":2,"skill":"sequence","stage":"production"},{"q":"Why should you make a list one week before the trip?","answer":"So you have time to find or wash everything you need.","explanation":"Reason.","explanation_ar":"سبب.","dok":2,"skill":"inference","stage":"production"},{"q":"Add one more step to the packing text. Where does it go on the timeline?","answer":"Two days before: charge your tablet. It goes between 'three days before' and 'the night before'.","explanation":"Step + place.","explanation_ar":"خطوة + مكانها.","dok":3,"skill":"apply","stage":"production"},{"q":"Write a timeline of four events from your last school day.","answer":"7:00 – the bus came; 9:00 – math test; 12:00 – lunch; 1:30 – I went home.","explanation":"Four timed events.","explanation_ar":"أربعة أحداث بأوقاتها.","dok":2,"skill":"personal timeline","stage":"production"}]},{"id":"RW-L03-U3-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"How to Pack for a Trip\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “How to Pack for a Trip”.","answer":"114 words","title":"How to Pack for a Trip","body":"Packing is easy when you follow the steps in the right order.\n\n**One week before:** Make a list of what you need: clothes, shoes, a toothbrush and a book for the journey.\n\n**Three days before:** Wash your favorite clothes so they are clean and ready.\n\n**The night before:** First, put heavy things like shoes at the bottom of your suitcase. Then, fold your clothes and put them on top. Finally, put your toothbrush and other small things in a side pocket.\n\n**On the morning of the trip:** Check your list one more time. Put your ticket, a snack and your book in your backpack.\n\nNow you are ready to go. Have a great journey!","words":114,"limit":112}],"time_limit_sec":112},{"id":"RW-L03-U3-LS3-ORG","type":"organizer","organizer":"Timeline","instructions":"Organizer: Draw a line. Write the time or date ABOVE the line and the event or step BELOW it, from first (left) to last (right).","items":[{"q":"1 – time/date + event","answer":"One week before – make a list of what you need"},{"q":"2 – time/date + event","answer":"Three days before – wash your favorite clothes"},{"q":"3 – time/date + event","answer":"The night before – pack: heavy things, then clothes, then small things"},{"q":"4 – time/date + event","answer":"On the morning of the trip – check the list; put the ticket in your backpack"}]}],"game":{"name":"Timeline Race","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Timeline dash: event cards drop onto the screen; the child drags them onto the timeline from left to right. A correct timeline starts a train that rides along it.","Each team gets a string and clothespins.","Start the timer: teams pin the history cards in order from left to right.","Then they pin the packing cards on a second string.","Teams read their timelines aloud with the dates and time phrases.","First correct team = 3 points; every correct timeline = 2 points."],"data":[]},"exit_quiz":[{"q":"When we put events on a timeline, *sequence* means ___.","answer":"the order in which things happen","explanation":"Sequence = order.","explanation_ar":"الترتيب.","options":["a kind of transport","a big suitcase","the end of a story","the order in which things happen"],"dok":1,"skill":"vocabulary"},{"q":"A timeline shows events ___.","answer":"in the order they happened","explanation":"Timeline = time order.","explanation_ar":"بترتيب حدوثها.","options":["in the order they happened","in ABC order","by size","by color"],"dok":1,"skill":"timelines"},{"q":"What is the purpose of *How to Pack for a Trip*?","answer":"to teach the steps for packing","explanation":"How-to = teach steps.","explanation_ar":"تعليم خطوات الحزم.","options":["to tell a funny story","to teach the steps for packing","to describe a camel","to give an opinion about trains"],"dok":1,"skill":"author's purpose"},{"q":"*Put heavy things at the bottom.* *Heavy* means ___.","answer":"weighing a lot","explanation":"Heavy = hard to lift.","explanation_ar":"ثقيل.","options":["very small","very fast","very clean","weighing a lot"],"dok":1,"skill":"vocabulary"},{"q":"Which packing step comes RIGHT AFTER washing your clothes?","answer":"packing your suitcase the night before","explanation":"Three days → the night before.","explanation_ar":"الحزم في الليلة السابقة.","options":["making a list","packing your suitcase the night before","checking your list in the morning","buying a ticket"],"dok":2,"skill":"sequence"},{"q":"Which event is the MOST RECENT?","answer":"the Haramain High-Speed Railway opened","explanation":"2018 is the latest.","explanation_ar":"قطار الحرمين.","options":["the Haramain High-Speed Railway opened","the Hejaz Railway reached Madinah","the first cars came to Arabia","people traveled by camel"],"dok":2,"skill":"sequence"},{"q":"Which sentence has the comma in the right place?","answer":"Then, fold your clothes and put them on top.","explanation":"Comma after Then.","explanation_ar":"الفاصلة بعد Then.","options":["Then fold, your clothes and put them on top.","Then fold your clothes, and put, them on top.","Then, fold your clothes and put them on top.","Then fold your clothes and put them, on top."],"dok":2,"skill":"punctuation"},{"q":"Why does the writer use time phrases like *the night before*?","answer":"to help the reader do the steps at the right time","explanation":"Time phrases guide the order.","explanation_ar":"ليقوم القارئ بالخطوات في وقتها.","options":["to help the reader do the steps at the right time","to make the text funny","to name the suitcase","to show it is a poem"],"dok":2,"skill":"author's craft"},{"q":"Which new step would come FIRST on the packing timeline?","answer":"Two weeks before: ask your parents about the trip dates.","explanation":"Two weeks is earliest.","explanation_ar":"قبل أسبوعين.","options":["Two days before: charge your tablet.","Two weeks before: ask your parents about the trip dates.","The night before: put snacks in your bag.","On the morning: put on your shoes."],"dok":3,"skill":"apply"},{"q":"What would happen if you checked your list BEFORE you made it?","answer":"It would not work, because there is no list yet.","explanation":"Some steps must come first.","explanation_ar":"لن ينجح لعدم وجود قائمة.","options":["Your trip would be faster.","Your clothes would be cleaner.","It would not work, because there is no list yet.","Nothing would change."],"dok":3,"skill":"reasoning"}],"images":[{"id":"IMG-RW-L03-U3-LS3-V01","prompt":"Picture for the word 'pack': a child packing a suitcase"},{"id":"IMG-RW-L03-U3-LS3-V02","prompt":"Picture for the word 'suitcase': a blue suitcase with wheels"},{"id":"IMG-RW-L03-U3-LS3-V03","prompt":"Picture for the word 'list': a checklist on a notepad"},{"id":"IMG-RW-L03-U3-LS3-V04","prompt":"Picture for the word 'heavy': a child lifting a heavy box"},{"id":"IMG-RW-L03-U3-LS3-V05","prompt":"Picture for the word 'backpack': a red backpack"},{"id":"IMG-RW-L03-U3-LS3-V06","prompt":"Picture for the word 'timeline': a line with dates and pictures"},{"id":"IMG-RW-L03-U3-LS3-V07","prompt":"Picture for the word 'before': a clock and an arrow pointing back"},{"id":"IMG-RW-L03-U3-LS3-01","prompt":"Sami and Lama pack a suitcase in the right order."},{"id":"IMG-RW-L03-U3-LS3-02","prompt":"A timeline organizer with four points."},{"id":"IMG-RW-L03-U3-LS3-03","prompt":"A timeline of transport from camels to high-speed trains."}],"audio":[{"id":"AUD-RW-L03-U3-LS3-V01","script":"pack. Pack your suitcase the night before."},{"id":"AUD-RW-L03-U3-LS3-V02","script":"suitcase. My suitcase is blue."},{"id":"AUD-RW-L03-U3-LS3-V03","script":"list. Make a list of what you need."},{"id":"AUD-RW-L03-U3-LS3-V04","script":"heavy. Put heavy things at the bottom."},{"id":"AUD-RW-L03-U3-LS3-V05","script":"backpack. Put your ticket in your backpack."},{"id":"AUD-RW-L03-U3-LS3-V06","script":"timeline. We made a timeline of transport."},{"id":"AUD-RW-L03-U3-LS3-V07","script":"before. Wash your clothes three days before the trip."},{"id":"AUD-RW-L03-U3-LS3-T1","script":"Packing is easy when you follow the steps in the right order. **One week before:** Make a list of what you need: clothes, shoes, a toothbrush and a book for the journey. **Three days before:** Wash your favorite clothes so they are clean and ready. **The night before:** First, put heavy things like shoes at the bottom of your suitcase. Then, fold your clothes and put them on top. Finally, put your toothbrush and other small things in a side pocket. **On the morning of the trip:** Check your list one more time. Put your ticket, a snack and your book in your backpack. Now you are ready to go. Have a great journey!"},{"id":"AUD-RW-L03-U3-LS3-VID","script":"Everything happens in order – history AND packing! Let's make timelines. Camels… 1908 railway… first cars… first planes… 2018 high-speed train! How to Pack for a Trip. One week before: make a list… Oops! Lama put the shoes on top of her clothes. Why does the order matter? Earliest on the left, latest on the right. Dates above, events below!"}]},{"id":"RW-L03-U3-LS4","title":"Writing Skill: Linking words: also, then, finally","lesson_type":"writing_skill","objectives":["use the linking words first, then, also, after that and finally to connect events in a recount","place also correctly before the main verb (We also watched…)","put a comma after linking words at the start of a sentence"],"objectives_ar":["استخدام كلمات الربط first وthen وalso وafter that وfinally لربط الأحداث في سرد.","وضع also في مكانها الصحيح قبل الفعل الرئيسي.","وضع فاصلة بعد كلمات الربط في بداية الجملة."],"success_criteria":["I can use first, then, after that and finally to show order.","I can use also to add another event or detail.","I can punctuate linking words correctly."],"success_criteria_ar":["أستطيع استخدام كلمات الترتيب لإظهار التسلسل.","أستطيع استخدام also لإضافة حدث أو تفصيل آخر.","أستطيع ترقيم كلمات الربط بشكل صحيح."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"recount","pos":"noun","ipa":"/ˈrikaʊnt/","definition":"writing that tells about something that really happened, in order","arabic":"سرد لأحداث حقيقية","example":"Layla wrote a recount of her trip.","image_id":"IMG-RW-L03-U3-LS4-V01","audio_id":"AUD-RW-L03-U3-LS4-V01","tier":"core"},{"word":"linking word","pos":"noun","ipa":"/ˈlɪŋkɪŋ wɝd/","definition":"a word that joins ideas or events (first, then, also, finally)","arabic":"كلمة ربط","example":"Linking words make writing smooth.","image_id":"IMG-RW-L03-U3-LS4-V02","audio_id":"AUD-RW-L03-U3-LS4-V02","tier":"core"},{"word":"also","pos":"adverb","ipa":"/ˈɔlsoʊ/","definition":"a word that adds one more thing","arabic":"أيضًا","example":"We also watched them make rose water.","image_id":"IMG-RW-L03-U3-LS4-V03","audio_id":"AUD-RW-L03-U3-LS4-V03","tier":"core"},{"word":"farmer","pos":"noun","ipa":"/ˈfɑrmər/","definition":"a person who works on a farm","arabic":"مزارع","example":"A farmer showed us the roses.","image_id":"IMG-RW-L03-U3-LS4-V04","audio_id":"AUD-RW-L03-U3-LS4-V04","tier":"core"},{"word":"rose water","pos":"noun","ipa":"/roʊz ˈwɔtər/","definition":"water with the smell of roses, made from rose petals","arabic":"ماء الورد","example":"Taif is famous for rose water.","image_id":"IMG-RW-L03-U3-LS4-V05","audio_id":"AUD-RW-L03-U3-LS4-V05","tier":"core"},{"word":"mountain","pos":"noun","ipa":"/ˈmaʊntən/","definition":"a very high hill","arabic":"جبل","example":"Taif is in the mountains.","image_id":"IMG-RW-L03-U3-LS4-V06","audio_id":"AUD-RW-L03-U3-LS4-V06","tier":"core"},{"word":"never forget","pos":"phrase","ipa":"/ˈnɛvər fərˈɡɛt/","definition":"always remember","arabic":"لن أنسى أبدًا","example":"I will never forget my first train ride.","image_id":"IMG-RW-L03-U3-LS4-V07","audio_id":"AUD-RW-L03-U3-LS4-V07","tier":"core"}],"explanation":{"text":"A **recount** tells about something that **really happened**, in **time order**. **Linking words** help the reader follow the events.\n\nTo show **order**: **First,** → **Then,** → **After that,** → **Finally,** (put a **comma** after them at the start of a sentence).\n\nTo **add** one more event or detail: **also**. Put *also* **before the main verb** (*We **also** watched…*) or **after am/is/are/was/were** (*It was **also** very cold.*).","examples":["**First,** we drove up the mountain road early in the morning.","**Then,** a farmer showed us how workers pick the roses.","We **also** watched them make rose water.","**After that,** I painted a picture of the rose fields.","**Finally,** we drove home with the windows open.","*also* after *was*: The air **was also** cool and fresh.","*also* with *can*: You **can also** buy rose oil at the farm.","Train trip: **First,** we bought our tickets. **Then,** we found our seats. We **also** ate dates. **Finally,** we arrived in Madinah.","Not every sentence needs a linking word – use them where they help the order."],"common_errors":["✗ Also, we watched them make rose water. → ✓ We also watched them make rose water. (At this level, put **also** before the main verb.)","✗ We watched also the farmer. → ✓ We also watched the farmer. (**also** goes **before** the main verb.)","✗ First we drove to Taif. → ✓ First, we drove to Taif. (Comma after **First**.)","✗ Then then then… → ✓ First, … Then, … After that, … Finally, … (Use **different** linking words.)","✗ Finally, we drove to the farm. (the first event) → ✓ First, we drove to the farm. (**Finally** is for the **last** event.)","✗ Last spring my family take a trip. → ✓ Last spring, my family took a trip. (Recounts are in the **past**: took, drove, watched.)"],"arabic":"السرد (recount) يحكي شيئًا حدث فعلًا بترتيب زمني، وكلمات الربط تساعد القارئ على متابعة الأحداث.\n\nلإظهار الترتيب: First, ثم Then, ثم After that, ثم Finally، مع فاصلة بعدها في بداية الجملة.\n\nلإضافة حدث أو تفصيل: also، وتوضع قبل الفعل الرئيسي (We also watched) أو بعد am/is/are/was/were (It was also cold).\n\nالسرد بالماضي: took, drove, watched, painted."},"video":{"script":[{"time":"00:00–00:20","narration":"Layla visited a rose farm in Taif. She wrote a recount – a true story in order!","on_screen":"Our Trip to the Rose Farm","visual":"Pink rose fields on a mountain; Layla with a sketchbook."},{"time":"00:20–01:10","narration":"Last spring, my family took a short trip to a rose farm near Taif. First, we drove…","on_screen":"(model recount)","visual":"Each event appears as a picture on a winding mountain road."},{"time":"01:10–01:45","narration":"Order words: First… Then… After that… Finally!","on_screen":"First → Then → After that → Finally","visual":"Road signs with the linking words appear along the road."},{"time":"01:45–02:25","narration":"Also adds one more thing: We ALSO watched them make rose water. Also goes before the verb!","on_screen":"also + verb","visual":"The word 'also' slides in front of 'watched'."},{"time":"02:25–03:00","narration":"Commas after linking words at the start of a sentence. Now link YOUR trip!","on_screen":"First, … Then, …","visual":"Commas hop after each linking word; Saqr smells a rose."}],"captions_ar":["زارت ليلى مزرعة ورد في الطائف وكتبت سردًا: قصة حقيقية بترتيب!","في الربيع الماضي قامت عائلتي برحلة قصيرة إلى مزرعة ورد قرب الطائف. أولًا…","كلمات الترتيب: First… Then… After that… Finally!","also تضيف شيئًا آخر، وتأتي قبل الفعل!","فاصلة بعد كلمات الربط في بداية الجملة. والآن اربط رحلتك!"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Layla (the Artist) reads her recount dreamily."},"texts":[{"type":"model","title":"Our Trip to the Rose Farm (by Layla)","body":"Last spring, my family took a short trip to a rose farm near Taif. First, we drove up the mountain road early in the morning. Then, a farmer showed us how workers pick the pink roses before the sun gets hot. We also watched them make rose water in big copper pots. After that, I painted a picture of the rose fields, and my brother bought a small bottle of rose oil for our mother. Finally, we drove home with the windows open, and the car smelled like roses all the way. I will never forget that sweet trip!","word_count":99,"audio_id":"AUD-RW-L03-U3-LS4-T1","id":"TXT-RW-L03-U3-LS4-1","genre":"model text","role":"model","difficulty":"350L–500L","glossary":[],"annotations":["**Last spring, … near Taif.** – the first sentence tells **when**, **who** and **where** (the topic sentence of a recount).","**First,** – the first event. **Then,** – the next event.","**We also watched…** – **also** adds **another** thing that happened at the same place. It goes **before the main verb** (also watched), not at the start with a comma here.","**After that,** – moves to the next event in time.","**Finally,** – the **last** event.","**I will never forget that sweet trip!** – the closing tells how the writer **feels** about the trip."]}],"activities":[{"id":"RW-L03-U3-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"Where did Layla's family go?","answer":"to a rose farm near Taif","explanation":"Model text.","explanation_ar":"مزرعة ورد قرب الطائف.","options":["to the beach in Jeddah","to an airport","to a rose farm near Taif","to a camel race"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Which linking word tells the LAST event in Layla's recount?","answer":"Finally,","explanation":"Finally = last.","explanation_ar":"Finally.","options":["First,","Then,","Finally,","After that,"],"dok":1,"skill":"linking words","stage":"controlled"},{"q":"Which linking word ADDS one more event or detail?","answer":"also","explanation":"also = add.","explanation_ar":"also.","options":["first","finally","before","also"],"dok":1,"skill":"linking words","stage":"controlled"},{"q":"What did the workers make in big copper pots?","answer":"rose water","explanation":"Model text.","explanation_ar":"ماء الورد.","options":["rose water","bread","juice","paint"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"A true story told in time order is a ___.","answer":"recount","explanation":"Recount = true events in order.","explanation_ar":"سرد.","options":["poem","letter","list","recount"],"dok":1,"skill":"genre","stage":"controlled"},{"q":"*I will never forget that trip.* This means ___.","answer":"I will always remember it","explanation":"Never forget = always remember.","explanation_ar":"سأتذكرها دائمًا.","options":["I forgot it","I will always remember it","It was boring","I will go tomorrow"],"dok":1,"skill":"vocabulary","stage":"controlled"}]},{"id":"RW-L03-U3-LS4-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Choose the correct sentence.","instructions_ar":"اختر الجملة الصحيحة.","items":[{"q":"Which sentence about the rose farm puts *also* in the right place?","answer":"We also watched them make rose water.","explanation":"also before the main verb.","explanation_ar":"قبل الفعل الرئيسي.","options":["We watched also them make rose water.","We also watched them make rose water.","We watched them also make rose water also.","Also we watched them make rose water also."],"dok":2,"skill":"also","stage":"guided"},{"q":"Which sentence about the mountain air uses *also* after *was*?","answer":"The air was also cool and fresh.","explanation":"was + also.","explanation_ar":"بعد was.","options":["The air was also cool and fresh.","The air also was cool also.","The air was cool also fresh.","Also the air cool was."],"dok":2,"skill":"also","stage":"guided"},{"q":"Which sentence about the drive has the comma in the right place?","answer":"First, we drove up the mountain road.","explanation":"Comma after First.","explanation_ar":"الفاصلة بعد First.","options":["First, we drove up the mountain road.","First we, drove up the mountain road.","First we drove, up the mountain road.","First we drove up the mountain, road."],"dok":1,"skill":"punctuation","stage":"guided"},{"q":"Choose the best linking word: *___, we bought our train tickets.* (the first event)","answer":"First","explanation":"The first event.","explanation_ar":"First.","options":["Finally","After that","Also","First"],"dok":1,"skill":"linking words","stage":"guided"},{"q":"Choose the best linking word: *___, we arrived in Madinah and hugged Grandma.* (the last event)","answer":"Finally","explanation":"The last event.","explanation_ar":"Finally.","options":["First","Finally","Then","Also"],"dok":1,"skill":"linking words","stage":"guided"},{"q":"Which sentence about the train trip is in the past tense?","answer":"Then, we found our seats on the train.","explanation":"Recounts use the past.","explanation_ar":"الماضي.","options":["Then, we find our seats on the train.","Then, we will find our seats.","Then, we found our seats on the train.","Then, we finding our seats."],"dok":2,"skill":"past tense","stage":"guided"}]},{"id":"RW-L03-U3-LS4-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Complete the recount of a train trip. Use the word bank.","instructions_ar":"أكمل سرد رحلة القطار من بنك الكلمات.","items":[{"q":"________, we took a taxi to the train station in Makkah.","answer":"First","explanation":"First event.","explanation_ar":"أولًا.","stage":"freer"},{"q":"________, we showed our tickets and found our seats.","answer":"Then","explanation":"Next event.","explanation_ar":"ثم.","stage":"freer"},{"q":"The train was fast. It was ________ very quiet and clean.","answer":"also","explanation":"Adds one more detail after was.","explanation_ar":"أيضًا.","stage":"freer"},{"q":"________, my sister and I ate dates and read our books.","answer":"After that","explanation":"Another event later.","explanation_ar":"بعد ذلك.","stage":"freer"},{"q":"________, we arrived in Madinah in less than three hours.","answer":"Finally","explanation":"Last event.","explanation_ar":"أخيرًا.","stage":"freer"},{"q":"I will ________ forget that fast journey!","answer":"never","explanation":"Always remember.","explanation_ar":"أبدًا.","stage":"freer"}]},{"id":"RW-L03-U3-LS4-A4","type":"open","stage":"production","instructions":"Writing: Write linked sentences.","instructions_ar":"اكتب جملًا مترابطة.","items":[{"q":"Write a first sentence for a recount: when, who and where.","answer":"Last summer, my family went to Abha by car.","explanation":"When + who + where.","explanation_ar":"متى + من + أين.","dok":1,"skill":"recount opening","stage":"production"},{"q":"Write two events with First and Then.","answer":"First, we drove through the green mountains. Then, we rode the cable car.","explanation":"Two linked events.","explanation_ar":"حدثان مترابطان.","dok":2,"skill":"linking words","stage":"production"},{"q":"Add a sentence with *also* before the main verb.","answer":"We also visited an old village with stone houses.","explanation":"also + verb.","explanation_ar":"also + فعل.","dok":2,"skill":"also","stage":"production"},{"q":"Write a last event with Finally and a closing about how you felt.","answer":"Finally, we watched the sunset from the mountain. I will never forget that beautiful evening!","explanation":"Finally + feeling.","explanation_ar":"Finally + شعور.","dok":3,"skill":"closing","stage":"production"}]}],"game":{"name":"Link the Journey","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Road link: event cards appear along a road; the child drags the right linking word onto each road sign. A correct road lets the family car drive to the destination.","Teams get the cards for one trip (Abha, Madinah by train, the rose farm, Jeddah beach).","They put the events in order on the road board.","They place a linking-word card before each event (one 'also' sentence must be rewritten correctly).","Teams read the whole recount aloud.","Correct order + linking words + 'also' sentence = 4 points."],"data":[]},"exit_quiz":[{"q":"What does a recount tell?","answer":"something that really happened, in time order","explanation":"Recount = true events in order.","explanation_ar":"أحداث حقيقية بالترتيب.","options":["how to make something","something that really happened, in time order","an opinion with reasons","a list of facts about animals"],"dok":1,"skill":"genre"},{"q":"Which linking word comes FIRST in a recount?","answer":"First,","explanation":"First = start.","explanation_ar":"First.","options":["Finally,","After that,","First,","Then,"],"dok":1,"skill":"linking words"},{"q":"*Also* is used to ___.","answer":"add another event or detail","explanation":"also = add.","explanation_ar":"إضافة حدث أو تفصيل.","options":["end the recount","ask a question","start a letter","add another event or detail"],"dok":1,"skill":"linking words"},{"q":"*Taif is in the mountains.* A mountain is ___.","answer":"a very high hill","explanation":"Mountain = high hill.","explanation_ar":"جبل.","options":["a big lake","a very high hill","a long road","a small garden"],"dok":1,"skill":"vocabulary"},{"q":"Which sentence about the cable car uses *also* correctly?","answer":"We also rode the cable car.","explanation":"also before the main verb.","explanation_ar":"صحيحة.","options":["We rode also the cable car.","We rode the cable car also also.","Also rode we the cable car.","We also rode the cable car."],"dok":2,"skill":"also"},{"q":"Fix it: *After that we ate lunch.*","answer":"After that, we ate lunch.","explanation":"Comma after After that.","explanation_ar":"فاصلة بعد After that.","options":["After, that we ate lunch.","After that we, ate lunch.","After that we ate, lunch.","After that, we ate lunch."],"dok":2,"skill":"punctuation"},{"q":"Which order of linking words is best for four events?","answer":"First, Then, After that, Finally","explanation":"Logical order.","explanation_ar":"الترتيب المنطقي.","options":["Finally, Then, First, After that","First, Then, After that, Finally","Then, Then, Then, Then","After that, First, Finally, Then"],"dok":2,"skill":"sequence"},{"q":"Why is a recount written in the past tense?","answer":"because the events already happened","explanation":"Past events → past tense.","explanation_ar":"لأن الأحداث وقعت فعلًا.","options":["because the events already happened","because it is about the future","because it is a poem","because it gives steps"],"dok":2,"skill":"grammar"},{"q":"Which closing sentence BEST ends a recount?","answer":"I will never forget that sweet trip!","explanation":"It tells the writer's feeling.","explanation_ar":"تختم بشعور.","options":["I will never forget that sweet trip!","First, we drove to the farm.","Roses are flowers.","How to make rose water."],"dok":3,"skill":"closing"},{"q":"Your friend's recount uses *Then* five times. What is the best advice?","answer":"Use different linking words like First, After that and Finally.","explanation":"Vary linking words.","explanation_ar":"نوّع كلمات الربط.","options":["Use Then ten times.","Remove all the events.","Use different linking words like First, After that and Finally.","Write it in the future tense."],"dok":3,"skill":"revising"}],"images":[{"id":"IMG-RW-L03-U3-LS4-V01","prompt":"Picture for the word 'recount': a diary page with a date and pictures"},{"id":"IMG-RW-L03-U3-LS4-V02","prompt":"Picture for the word 'linking word': chain links labelled first, then, finally"},{"id":"IMG-RW-L03-U3-LS4-V03","prompt":"Picture for the word 'also': a plus sign"},{"id":"IMG-RW-L03-U3-LS4-V04","prompt":"Picture for the word 'farmer': a farmer holding a basket of roses"},{"id":"IMG-RW-L03-U3-LS4-V05","prompt":"Picture for the word 'rose water': a glass bottle of rose water with petals"},{"id":"IMG-RW-L03-U3-LS4-V06","prompt":"Picture for the word 'mountain': green mountains with a winding road"},{"id":"IMG-RW-L03-U3-LS4-V07","prompt":"Picture for the word 'never forget': a child hugging a photo album"},{"id":"IMG-RW-L03-U3-LS4-01","prompt":"Pink rose fields and a rose-water workshop near Taif."},{"id":"IMG-RW-L03-U3-LS4-02","prompt":"Road signs showing linking words."},{"id":"IMG-RW-L03-U3-LS4-03","prompt":"The word 'also' going before the verb."}],"audio":[{"id":"AUD-RW-L03-U3-LS4-V01","script":"recount. Layla wrote a recount of her trip."},{"id":"AUD-RW-L03-U3-LS4-V02","script":"linking word. Linking words make writing smooth."},{"id":"AUD-RW-L03-U3-LS4-V03","script":"also. We also watched them make rose water."},{"id":"AUD-RW-L03-U3-LS4-V04","script":"farmer. A farmer showed us the roses."},{"id":"AUD-RW-L03-U3-LS4-V05","script":"rose water. Taif is famous for rose water."},{"id":"AUD-RW-L03-U3-LS4-V06","script":"mountain. Taif is in the mountains."},{"id":"AUD-RW-L03-U3-LS4-V07","script":"never forget. I will never forget my first train ride."},{"id":"AUD-RW-L03-U3-LS4-T1","script":"Last spring, my family took a short trip to a rose farm near Taif. First, we drove up the mountain road early in the morning. Then, a farmer showed us how workers pick the pink roses before the sun gets hot. We also watched them make rose water in big copper pots. After that, I painted a picture of the rose fields, and my brother bought a small bottle of rose oil for our mother. Finally, we drove home with the windows open, and the car smelled like roses all the way. I will never forget that sweet trip!"},{"id":"AUD-RW-L03-U3-LS4-VID","script":"Layla visited a rose farm in Taif. She wrote a recount – a true story in order! Last spring, my family took a short trip to a rose farm near Taif. First, we drove… Order words: First… Then… After that… Finally! Also adds one more thing: We ALSO watched them make rose water. Also goes before the verb! Commas after linking words at the start of a sentence. Now link YOUR trip!"}]},{"id":"RW-L03-U3-LS5","title":"Writing Workshop: A Trip I Will Never Forget","lesson_type":"writing_workshop","objectives":["plan a recount of a real trip with a Story Mountain: setting, events, the most exciting moment and the ending","write a 6–8-sentence recount paragraph in the past tense with linking words and a closing feeling","revise for order and detail, edit past-tense verbs and publish the recount as a 'travel postcard'"],"objectives_ar":["التخطيط لسرد رحلة حقيقية بجبل القصة: الإطار والأحداث واللحظة الأكثر إثارة والنهاية.","كتابة فقرة سرد من 6–8 جمل بالماضي مع كلمات الربط وجملة ختامية عن الشعور.","التحسين للترتيب والتفاصيل، وتدقيق أفعال الماضي، ونشر السرد على «بطاقة سفر»."],"success_criteria":["I can tell when, who and where in my first sentence.","I can tell the events in order with linking words.","I can use past-tense verbs correctly."],"success_criteria_ar":["أستطيع ذكر متى ومن وأين في جملتي الأولى.","أستطيع سرد الأحداث بالترتيب مع كلمات الربط.","أستطيع استخدام أفعال الماضي بشكل صحيح."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"platform","pos":"noun","ipa":"/ˈplætfɔrm/","definition":"the place at a station where you get on the train","arabic":"رصيف المحطة","example":"We waited on the platform.","image_id":"IMG-RW-L03-U3-LS5-V01","audio_id":"AUD-RW-L03-U3-LS5-V01","tier":"core"},{"word":"traffic","pos":"noun","ipa":"/ˈtræfɪk/","definition":"many cars on the road at the same time","arabic":"زحام المرور","example":"We were late because of the traffic.","image_id":"IMG-RW-L03-U3-LS5-V02","audio_id":"AUD-RW-L03-U3-LS5-V02","tier":"core"},{"word":"exciting","pos":"adjective","ipa":"/ɪkˈsaɪtɪŋ/","definition":"making you feel very happy and full of energy","arabic":"مثير / ممتع جدًا","example":"The fast train was exciting.","image_id":"IMG-RW-L03-U3-LS5-V03","audio_id":"AUD-RW-L03-U3-LS5-V03","tier":"core"},{"word":"arrive","pos":"verb","ipa":"/əˈraɪv/","definition":"to reach a place at the end of a journey","arabic":"يصل","example":"We arrived in Madinah at noon.","image_id":"IMG-RW-L03-U3-LS5-V04","audio_id":"AUD-RW-L03-U3-LS5-V04","tier":"core"},{"word":"memory","pos":"noun","ipa":"/ˈmɛməri/","definition":"something you remember from the past","arabic":"ذكرى","example":"That trip is my best memory.","image_id":"IMG-RW-L03-U3-LS5-V05","audio_id":"AUD-RW-L03-U3-LS5-V05","tier":"core"},{"word":"setting","pos":"noun","ipa":"/ˈsɛtɪŋ/","definition":"when and where a story or recount happens","arabic":"الإطار الزمني والمكاني","example":"The setting is a train station in Makkah.","image_id":"IMG-RW-L03-U3-LS5-V06","audio_id":"AUD-RW-L03-U3-LS5-V06","tier":"core"},{"word":"postcard","pos":"noun","ipa":"/ˈpoʊstkɑrd/","definition":"a card with a picture that you send from a trip","arabic":"بطاقة بريدية","example":"I sent Grandpa a postcard from Madinah.","image_id":"IMG-RW-L03-U3-LS5-V07","audio_id":"AUD-RW-L03-U3-LS5-V07","tier":"core"}],"explanation":{"text":"A **recount** tells a **true** event in **time order**. Choose **one special trip** – near or far, short or long.\n\nPlan with the **Story Mountain**: **setting** (when, who, where) → **events** in order → the **most exciting moment** (the top of the mountain – maybe a small problem!) → **ending** (how it finished and how you **felt**).\n\nWrite in the **past tense** (went, saw, took, arrived). Use **linking words** (First, Then, also, After that, Finally) and finish with a **closing** about your feeling or memory.","examples":["Setting: **Last winter, my family took the high-speed train from Makkah to Madinah.**","Event 1: **First, we left our house early, but the traffic was very heavy.**","Event 2 (exciting moment): **When we arrived at the station, the train was almost ready to leave, so we ran to the platform!**","Event 3: **Then, we found our seats just in time.**","Event 4: **The train went so fast that the desert looked like a yellow river. We also ate dates and drank Arabic coffee from Mom's flask.**","Ending: **Finally, we arrived in Madinah in less than three hours.**","Closing: **I will never forget that exciting race to catch the train!**","Other trip ideas: a visit to Grandpa's farm, a day at Jeddah Corniche, a trip to Abha, Umrah with your family, a school trip to a museum.","Senses make it vivid: what you **saw**, **heard**, **smelled** or **tasted**."],"common_errors":["✗ We go to Madinah last winter. → ✓ We went to Madinah last winter. (Use the **past tense** for a recount.)","✗ We arrive in Madinah. → ✓ We arrived in Madinah. (Past: arrive → **arrived**.)","✗ We runned to the platform. → ✓ We ran to the platform. (Irregular past: run → **ran**.)","✗ Telling about three different trips. → ✓ Tell about **one** trip. (One recount = one trip.)","✗ No feeling at the end. → ✓ I will never forget that exciting race to catch the train! (End with a feeling or memory.)","✗ First we left. then we ran. → ✓ First, we left. Then, we ran. (Comma after linking words; capital after a period.)"],"arabic":"السرد يحكي حدثًا حقيقيًا بترتيب زمني. اختر رحلة واحدة مميزة، قريبة أو بعيدة، قصيرة أو طويلة.\n\nخطط بجبل القصة: الإطار (متى ومن وأين) ← الأحداث بالترتيب ← اللحظة الأكثر إثارة (قمة الجبل، وقد تكون مشكلة صغيرة) ← النهاية وشعورك.\n\nاكتب بالماضي (went, saw, took, arrived) واستخدم كلمات الربط، واختم بشعورك أو ذكرياتك.\n\nالحواس تجعل السرد حيًّا: ما رأيته وسمعته وشممته وتذوقته."},"video":{"script":[{"time":"00:00–00:20","narration":"Sami had an exciting trip on the high-speed train. He will never forget it!","on_screen":"A Trip I Will Never Forget","visual":"Sami's family in a car stuck in traffic, Sami looking at the clock."},{"time":"00:20–00:55","narration":"Plan with a Story Mountain: setting, events, the exciting moment at the top, the ending.","on_screen":"1 Plan – Story Mountain ⛰️","visual":"A mountain fills with Sami's notes and small icons."},{"time":"00:55–01:55","narration":"Last winter, my family took the high-speed train from Makkah to Madinah. First, we left our house early, but the traffic…","on_screen":"2 Draft – past tense + linking words","visual":"The family runs to the platform; the doors close just after them."},{"time":"01:55–02:20","narration":"Revise: add a sense detail! The desert looked like a yellow river.","on_screen":"3 Revise ➕ senses 👀👂👃","visual":"A plain sentence turns colorful as a detail is added."},{"time":"02:20–02:40","narration":"Edit: past-tense verbs – go → went, run → ran, arrive → arrived!","on_screen":"4 Edit – past tense","visual":"Verbs flip from present to past like cards."},{"time":"02:40–03:00","narration":"Publish: Sami writes his recount on a travel postcard and draws the train!","on_screen":"5 Publish 📮","visual":"A wall of postcards titled 'Trips We Will Never Forget'."}],"captions_ar":["قام سامي برحلة مثيرة بالقطار السريع، ولن ينساها أبدًا!","خطّط بجبل القصة: الإطار، والأحداث، واللحظة المثيرة في القمة، والنهاية.","في الشتاء الماضي ركبت عائلتي القطار السريع من مكة إلى المدينة. أولًا غادرنا المنزل مبكرًا لكن الزحام…","التحسين: أضف تفصيلًا حسيًّا! بدت الصحراء كنهر أصفر.","التدقيق: أفعال الماضي: go ← went، run ← ran، arrive ← arrived!","النشر: يكتب سامي سرده على بطاقة سفر ويرسم القطار!"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Sami reads his recount with excitement and a little suspense."},"texts":[],"activities":[{"id":"RW-L03-U3-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"Which first sentence tells when, who and where?","answer":"Last winter, my family took the train from Makkah to Madinah.","explanation":"When + who + where.","explanation_ar":"متى ومن وأين.","options":["Last winter, my family took the train from Makkah to Madinah.","Trains are fast.","I like trips.","Then, we ran."],"dok":1,"skill":"recount opening","stage":"controlled"},{"q":"Where do you wait to get on a train?","answer":"on the platform","explanation":"Platform = train waiting area.","explanation_ar":"على الرصيف.","options":["on the highway","in the suitcase","on the platform","at the seaport"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Many cars on the road at the same time is ___.","answer":"traffic","explanation":"Traffic = many cars.","explanation_ar":"زحام.","options":["a platform","traffic","a postcard","a memory"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"*We arrived in Madinah at noon.* *Arrived* means ___.","answer":"reached the place","explanation":"Arrive = reach.","explanation_ar":"وصلنا.","options":["reached the place","left the place","lost the way","bought a ticket"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"What is the past tense of *run*?","answer":"ran","explanation":"Irregular past.","explanation_ar":"ran.","options":["runned","runs","ran","running"],"dok":1,"skill":"past tense","stage":"controlled"},{"q":"Which detail uses a SENSE?","answer":"The desert looked like a yellow river.","explanation":"looked = seeing.","explanation_ar":"حاسة البصر.","options":["We went to Madinah.","The train had seats.","We arrived.","The desert looked like a yellow river."],"dok":2,"skill":"sense details","stage":"controlled"}]},{"id":"RW-L03-U3-LS5-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the recount in order.","instructions_ar":"رتّب السرد.","items":[{"q":"Order Sami's recount.","answer":"Last winter, my family took the train to Madinah. → First, we left our house early. → Then, we ran to the platform. → Finally, we arrived in Madinah. → I will never forget that trip!","explanation":"setting → events → ending → feeling.","explanation_ar":"إطار ← أحداث ← نهاية ← شعور.","stage":"guided","parts":["Last winter, my family took the train to Madinah.","Finally, we arrived in Madinah.","I will never forget that trip!","Then, we ran to the platform.","First, we left our house early."],"target":["Last winter, my family took the train to Madinah.","First, we left our house early.","Then, we ran to the platform.","Finally, we arrived in Madinah.","I will never forget that trip!"]},{"q":"Build an 'also' sentence about the train.","answer":"We also ate dates.","explanation":"also before the main verb.","explanation_ar":"also قبل الفعل.","stage":"guided","parts":["dates.","We","ate","also"],"target":["We","also","ate","dates."]},{"q":"Build the exciting moment.","answer":"When we arrived, → the train → was almost → ready to leave!","explanation":"The exciting moment.","explanation_ar":"اللحظة المثيرة.","stage":"guided","parts":["was almost","the train","When we arrived,","ready to leave!"],"target":["When we arrived,","the train","was almost","ready to leave!"]},{"q":"Build a setting sentence about Abha.","answer":"Last summer, we drove to Abha.","explanation":"When + who + where.","explanation_ar":"متى + من + أين.","stage":"guided","parts":["Last summer,","to Abha.","we drove"],"target":["Last summer,","we drove","to Abha."]},{"q":"Build a sense detail about Abha.","answer":"The cool air → smelled like → pine trees.","explanation":"A smell detail.","explanation_ar":"تفصيل شمّي.","stage":"guided","parts":["pine trees.","smelled like","The cool air"],"target":["The cool air","smelled like","pine trees."]},{"q":"Build a closing sentence for a recount about a trip.","answer":"I will never forget that day!","explanation":"Closing feeling.","explanation_ar":"شعور ختامي.","stage":"guided","parts":["I will","that day!","never forget"],"target":["I will","never forget","that day!"]}]},{"id":"RW-L03-U3-LS5-A3","type":"organizer","stage":"freer","instructions":"Organizer: Plan your recount on the Story Mountain.","instructions_ar":"خطط لسردك على جبل القصة.","items":[{"q":"Setting: when, who, where.","answer":"last summer; my family and I; Jeddah Corniche","explanation":"Three parts.","explanation_ar":"ثلاثة أجزاء.","dok":1,"skill":"planning","stage":"freer"},{"q":"Write notes for two events before the exciting moment.","answer":"drove to Jeddah; walked by the sea","explanation":"Two events.","explanation_ar":"حدثان.","dok":1,"skill":"planning","stage":"freer"},{"q":"What was the most exciting moment?","answer":"a big wave splashed us, and we laughed","explanation":"The top of the mountain.","explanation_ar":"قمة الجبل.","dok":2,"skill":"planning","stage":"freer"},{"q":"Write notes for the ending and your feeling.","answer":"ate grilled fish and watched the fountain; happy and tired","explanation":"Ending + feeling.","explanation_ar":"نهاية + شعور.","dok":2,"skill":"planning","stage":"freer"}]},{"id":"RW-L03-U3-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Write, revise, edit and publish your recount.","instructions_ar":"اكتب سردك وحسّنه ودققه وانشره.","items":[{"q":"Write your setting sentence and your first two events with linking words.","answer":"Last summer, my family drove to Jeddah. First, we walked along the Corniche. Then, we watched the big fountain.","explanation":"Setting + 2 events.","explanation_ar":"إطار + حدثان.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your most exciting moment and one sense detail.","answer":"Suddenly, a big wave splashed us, and we all laughed. The sea smelled salty and fresh.","explanation":"Exciting moment + sense.","explanation_ar":"لحظة مثيرة + حاسة.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your ending with Finally and a closing feeling.","answer":"Finally, we ate grilled fish by the sea. I will never forget that happy evening!","explanation":"Finally + feeling.","explanation_ar":"Finally + شعور.","dok":2,"skill":"writing","stage":"production"},{"q":"Write two verbs you changed to the past tense.","answer":"go → went, see → saw","explanation":"Two verbs.","explanation_ar":"فعلان.","dok":3,"skill":"editing","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L03-U3-LS5-ORG","type":"organizer","organizer":"Story Mountain","instructions":"Organizer: Write your notes from the bottom left (setting) up to the top (the most exciting moment) and down to the ending.","items":[{"q":"Setting – when, who, where","answer":"last winter; my family; high-speed train Makkah → Madinah"},{"q":"Event 1","answer":"left early, heavy traffic"},{"q":"Event 2","answer":"arrived at the station, train almost leaving"},{"q":"Top – the most exciting moment","answer":"ran to the platform and found our seats just in time"},{"q":"Event after the top","answer":"train very fast; desert like a yellow river; ate dates"},{"q":"Ending + feeling","answer":"arrived in less than 3 hours – I will never forget it!"}]},{"id":"RW-L03-U3-LS5-WR","type":"writing","instructions":"Writing: Write a recount paragraph: \"A Trip I Will Never Forget\" (6–8 sentences). Tell when, who and where, the events in order with linking words, the most exciting moment and how you felt. Write a recount paragraph: \"A Trip I Will Never Forget\" (6–8 sentences). Tell when, who and where, the events in order with linking words, the most exciting moment and how you felt.","instructions_ar":"اكتب فقرة سرد بعنوان «رحلة لن أنساها» (6–8 جمل): متى ومن وأين، والأحداث بالترتيب مع كلمات الربط، واللحظة الأكثر إثارة، وشعورك.","prompt":"Write a recount paragraph: \"A Trip I Will Never Forget\" (6–8 sentences). Tell when, who and where, the events in order with linking words, the most exciting moment and how you felt.","checklist":["My first sentence tells when, who and where.","My events are in time order.","I used at least three linking words (First, Then, also, After that, Finally).","I told the most exciting moment.","I added a sense detail.","All my verbs are in the past tense (went, saw, arrived…).","I ended with a feeling or memory; commas and capitals are correct."],"rubric_id":"RW-RUBRIC-5T","min_words":75,"max_words":150,"organizer":"Story Mountain (setting → events → exciting moment → ending)","items":[{"q":"Write a recount paragraph: \"A Trip I Will Never Forget\" (6–8 sentences). Tell when, who and where, the events in order with linking words, the most exciting moment and how you felt.","answer":"Last winter, my family took the high-speed train from Makkah to Madinah. First, we left our house early, but the traffic was very heavy. When we arrived at the station, the train was almost ready to leave, so we ran to the platform! Then, we found our seats just in time. The train went so fast that the desert looked like a yellow river. We also ate dates and drank Arabic coffee from Mom's flask. Finally, we arrived in Madinah in less than three hours. I will never forget that exciting race to catch the train!","_w":{"checklist":["My first sentence tells when, who and where.","My events are in time order.","I used at least three linking words (First, Then, also, After that, Finally).","I told the most exciting moment.","I added a sense detail.","All my verbs are in the past tense (went, saw, arrived…).","I ended with a feeling or memory; commas and capitals are correct."],"min":75,"max":150}}]}],"game":{"name":"Past-Tense Postcards","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Postcard fixer: a postcard shows sentences with present verbs in red; the child taps each red verb and chooses the past form, then drags the sentences into order. A finished postcard flies to Grandpa's mailbox.","Each team opens an envelope with one trip's sentences.","Teams change every verb to the past tense.","Teams put the sentences in order with linking words.","Teams read their postcard aloud.","Each correct verb = 1 point; correct order = 3 points."],"data":[]},"exit_quiz":[{"q":"A recount is written in the ___ tense.","answer":"past","explanation":"Events already happened.","explanation_ar":"الماضي.","options":["future","past","present only","question"],"dok":1,"skill":"grammar"},{"q":"The setting of a recount tells ___.","answer":"when and where it happened","explanation":"Setting = when and where.","explanation_ar":"متى وأين.","options":["the last event","the feelings only","when and where it happened","the title"],"dok":1,"skill":"story elements"},{"q":"What goes at the TOP of the Story Mountain?","answer":"the most exciting moment","explanation":"Top = most exciting.","explanation_ar":"اللحظة الأكثر إثارة.","options":["the setting","the ending","the title","the most exciting moment"],"dok":1,"skill":"organizer"},{"q":"*That trip is my best memory.* A memory is ___.","answer":"something you remember","explanation":"Memory = remembered thing.","explanation_ar":"ذكرى.","options":["a ticket","something you remember","a platform","a kind of train"],"dok":1,"skill":"vocabulary"},{"q":"What is the past tense of *take*?","answer":"took","explanation":"Irregular past.","explanation_ar":"took.","options":["taked","takes","took","taken"],"dok":1,"skill":"past tense"},{"q":"Which sentence about the trip to Abha is correct?","answer":"Last summer, we drove to Abha.","explanation":"Past → drove.","explanation_ar":"صحيحة.","options":["Last summer, we drive to Abha.","Last summer, we drived to Abha.","Last summer, we drove to Abha.","Last summer, we will drive to Abha."],"dok":2,"skill":"grammar"},{"q":"Which sentence adds a SOUND detail?","answer":"We heard the waves crash on the rocks.","explanation":"heard = sound.","explanation_ar":"تفصيل صوتي.","options":["We went to the beach.","The beach is in Jeddah.","We arrived at five.","We heard the waves crash on the rocks."],"dok":2,"skill":"sense details"},{"q":"Which closing sentence ends a recount best?","answer":"I will never forget that happy day at the sea!","explanation":"Feeling at the end.","explanation_ar":"خاتمة بشعور.","options":["Last summer, we went to Jeddah.","I will never forget that happy day at the sea!","First, we drove.","Jeddah has a fountain."],"dok":2,"skill":"closing"},{"q":"Why is the most exciting moment important in a recount?","answer":"It makes the reader want to keep reading.","explanation":"It is the high point.","explanation_ar":"يشد القارئ.","options":["It makes the reader want to keep reading.","It replaces the setting.","It should come first.","It is not important."],"dok":3,"skill":"author's craft"},{"q":"A partner's recount tells about three different trips. What is the best advice?","answer":"Choose one trip and add more details about it.","explanation":"One recount = one trip.","explanation_ar":"اختر رحلة واحدة.","options":["Choose one trip and add more details about it.","Add a fourth trip.","Write it in the future tense.","Remove the linking words."],"dok":3,"skill":"revising"}],"images":[{"id":"IMG-RW-L03-U3-LS5-V01","prompt":"Picture for the word 'platform': people waiting on a train platform"},{"id":"IMG-RW-L03-U3-LS5-V02","prompt":"Picture for the word 'traffic': a busy road full of cars"},{"id":"IMG-RW-L03-U3-LS5-V03","prompt":"Picture for the word 'exciting': a child with arms up on a roller coaster"},{"id":"IMG-RW-L03-U3-LS5-V04","prompt":"Picture for the word 'arrive': a family stepping off a train with smiles"},{"id":"IMG-RW-L03-U3-LS5-V05","prompt":"Picture for the word 'memory': a photo album open on a table"},{"id":"IMG-RW-L03-U3-LS5-V06","prompt":"Picture for the word 'setting': a clock and a map pin"},{"id":"IMG-RW-L03-U3-LS5-V07","prompt":"Picture for the word 'postcard': a postcard with a picture of a mosque"},{"id":"IMG-RW-L03-U3-LS5-01","prompt":"Sami's family runs to catch the high-speed train."},{"id":"IMG-RW-L03-U3-LS5-02","prompt":"A Story Mountain organizer for a recount."},{"id":"IMG-RW-L03-U3-LS5-03","prompt":"A classroom wall of travel postcards."}],"audio":[{"id":"AUD-RW-L03-U3-LS5-V01","script":"platform. We waited on the platform."},{"id":"AUD-RW-L03-U3-LS5-V02","script":"traffic. We were late because of the traffic."},{"id":"AUD-RW-L03-U3-LS5-V03","script":"exciting. The fast train was exciting."},{"id":"AUD-RW-L03-U3-LS5-V04","script":"arrive. We arrived in Madinah at noon."},{"id":"AUD-RW-L03-U3-LS5-V05","script":"memory. That trip is my best memory."},{"id":"AUD-RW-L03-U3-LS5-V06","script":"setting. The setting is a train station in Makkah."},{"id":"AUD-RW-L03-U3-LS5-V07","script":"postcard. I sent Grandpa a postcard from Madinah."},{"id":"AUD-RW-L03-U3-LS5-VID","script":"Sami had an exciting trip on the high-speed train. He will never forget it! Plan with a Story Mountain: setting, events, the exciting moment at the top, the ending. Last winter, my family took the high-speed train from Makkah to Madinah. First, we left our house early, but the traffic… Revise: add a sense detail! The desert looked like a yellow river. Edit: past-tense verbs – go → went, run → ran, arrive → arrived! Publish: Sami writes his recount on a travel postcard and draws the train!"}]}],"unit_test":[{"q":"Ships stop at a ___ to load and unload goods.","answer":"seaport","explanation":"Ships → seaport.","explanation_ar":"ميناء.","options":["railway","platform","seaport","highway"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"A person who rides on a bus but does not drive it is a ___.","answer":"passenger","explanation":"Passenger.","explanation_ar":"راكب.","options":["passenger","pilot","farmer","traveler's map"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"Before you board the plane, you show your ___.","answer":"ticket","explanation":"Ticket = shows you paid.","explanation_ar":"تذكرتك.","options":["platform","highway","seatbelt","ticket"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"Which road word in this list is a compound word?","answer":"highway","explanation":"high + way.","explanation_ar":"highway.","options":["station","highway","journey","passenger"],"dok":1,"skill":"compound words","_part":"Part A – Vocabulary"},{"q":"A *seatbelt* is ___.","answer":"a belt on a seat that keeps you safe","explanation":"seat + belt.","explanation_ar":"حزام المقعد.","options":["a belt on a seat that keeps you safe","a seat on a bus","a kind of ticket","a belt for a suitcase"],"dok":2,"skill":"compound words","_part":"Part A – Vocabulary"},{"q":"Which word is in the same family as *fly*?","answer":"flight","explanation":"fly → flight.","explanation_ar":"flight.","options":["train","ship","flight","ticket"],"dok":2,"skill":"word families","_part":"Part A – Vocabulary"},{"q":"*The first cars were **invented** more than 100 years ago.* *Invented* means ___.","answer":"made for the first time","explanation":"Invent = make something new.","explanation_ar":"اختُرعت.","options":["sold in shops","driven fast","fixed","made for the first time"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"Which sentence about going to Abha is correct?","answer":"We went to Abha by car.","explanation":"by + transport.","explanation_ar":"by car.","options":["We went to Abha by the car.","We went to Abha by car.","We went to Abha with car.","We went to Abha in by car."],"dok":2,"skill":"grammar","_part":"Part A – Vocabulary"},{"q":"Which sentence uses *also* in the right place?","answer":"We also visited the old market.","explanation":"also before the main verb.","explanation_ar":"صحيحة.","options":["We visited also the old market.","We also visited the old market.","Also we visited also the market.","We visited the old also market."],"dok":1,"skill":"also","_part":"Part D – Recount skills"},{"q":"Which sentence about the airport has the comma in the right place?","answer":"After that, we waited at the gate.","explanation":"Comma after After that.","explanation_ar":"الفاصلة بعد After that.","options":["After that we, waited at the gate.","After that, we waited at the gate.","After, that we waited at the gate.","After that we waited, at the gate."],"dok":1,"skill":"punctuation","_part":"Part D – Recount skills"},{"q":"What is the past tense of *fly*?","answer":"flew","explanation":"Irregular past.","explanation_ar":"flew.","options":["flew","flied","flyed","flown"],"dok":1,"skill":"past tense","_part":"Part D – Recount skills"},{"q":"Which first sentence of a recount is best?","answer":"Last spring, my class visited the National Museum in Riyadh.","explanation":"When + who + where.","explanation_ar":"متى ومن وأين.","options":["Last spring, my class visited the National Museum in Riyadh.","Museums are big.","Then, we saw a camel.","I will never forget it."],"dok":2,"skill":"recount opening","_part":"Part D – Recount skills"},{"q":"On a timeline, which date goes on the LEFT?","answer":"1817","explanation":"Earliest on the left.","explanation_ar":"1817.","options":["1880","1870","1817","today"],"dok":2,"skill":"timelines","_part":"Part D – Recount skills"},{"q":"Which linking words show the order of events best?","answer":"First, Then, After that, Finally","explanation":"Logical order.","explanation_ar":"الترتيب المنطقي.","options":["Finally, First, Then, After that","Then, Then, Then, Then","After that, Finally, First, Then","First, Then, After that, Finally"],"dok":1,"skill":"linking words","_part":"Part D – Recount skills"}],"unit_writing":{"task":"Write a recount about a day out with your family or class (a park, a farm, a museum, the beach). Tell when, who and where, the events in order with linking words (First, Then, also, After that, Finally), one exciting moment, one sense detail and how you felt.","model":"Last spring, my class visited a camel farm near Taif. First, we rode the school bus through the mountains. Then, the farmer showed us how he feeds the baby camels. We also tasted fresh camel milk; it was warm and a little salty. After that, a young camel walked right up to me and touched my hand with its soft nose! Everyone laughed. Finally, we thanked the farmer and rode the bus back to school. I will never forget that funny camel!","marks":20}});
